test('dashboard queue view orders same-timestamp queued rows by queueSequence, not alphabetically', () => {
    const {sw} = loadServiceWorkerHarness()

    // A bulk enqueue stamps every row with the same createdAt/queuedAt
    // millisecond, so the view's time-based sort is a wash across the whole
    // batch. Before the 2026-09-14 fix, the fallback tiebreak was a plain
    // alphabetical key sort with no relation to queueSequence -- the order
    // the executor actually runs rows in -- so a row far back in line could
    // render at the very top of the dashboard's queue list and look stuck.
    const queue = {
        'https://www.quora.com/profile/Zebra': {
            status: 'queued',
            queuedAt: 1000,
            updatedAt: 1000,
            queueSequence: 1
        },
        'https://www.quora.com/profile/Mango': {
            status: 'queued',
            queuedAt: 1000,
            updatedAt: 1000,
            queueSequence: 2
        },
        'https://www.quora.com/profile/Apple': {
            status: 'queued',
            queuedAt: 1000,
            updatedAt: 1000,
            queueSequence: 3
        }
    }

    const queueView = sw.buildCoordinatorQueueView(queue, 5000)
    const orderedKeys = queueView.items.map(item => item.storageKey)

    assert.deepEqual(orderedKeys, [
        'https://www.quora.com/profile/Zebra',
        'https://www.quora.com/profile/Mango',
        'https://www.quora.com/profile/Apple'
    ])
})

test('dashboard queue view shows queued rows in real dispatch order, not most-recently-added first', () => {
    // 2026-09-16 nit: the queued-rank tiebreak used to be time descending,
    // same as every other rank -- fine for 'active' (surfacing recent
    // activity), backwards for 'queued': it put the row that was just
    // added at the top and the row actually next in line (the front of the
    // FIFO queue queueRuntime.rebuildQueueOrder walks by queueSequence
    // ascending) at the bottom. A row added later but with an earlier
    // queueSequence must still sort ahead of one added more recently.
    const {sw} = loadServiceWorkerHarness()
    const queue = {
        'https://www.quora.com/profile/Sort-Order-Recently-Added': {
            status: 'queued',
            queuedAt: 5000,
            updatedAt: 5000,
            queueSequence: 9
        },
        'https://www.quora.com/profile/Sort-Order-Front-Of-Line': {
            status: 'queued',
            queuedAt: 1000,
            updatedAt: 1000,
            queueSequence: 1
        }
    }

    const queueView = sw.buildCoordinatorQueueView(queue, 5000)
    const orderedKeys = queueView.items.map(item => item.storageKey)

    assert.deepEqual(orderedKeys, [
        'https://www.quora.com/profile/Sort-Order-Front-Of-Line',
        'https://www.quora.com/profile/Sort-Order-Recently-Added'
    ])
    assert.equal(queueView.items[0].queueSequence, 1)
})

