function trackServiceWorkerHarness(harness) {
    if(harness && typeof harness === 'object') {
        currentTestHarnesses.push(harness)
    }
    return harness
}

function cleanupTrackedServiceWorkerHarnesses() {
    const cleanupErrors = []
    const seen = new Set()
    const harnesses = currentTestHarnesses
    currentTestHarnesses = []

    for(let index = harnesses.length - 1; index >= 0; index -= 1) {
        const harness = harnesses[index]
        if(!harness || seen.has(harness)) continue
        seen.add(harness)
        try {
            if(typeof harness.sw?.__testDeactivateHarness === 'function') {
                harness.sw.__testDeactivateHarness()
            }
        }
        catch(error) {
            cleanupErrors.push(error)
        }
        try {
            if(typeof harness.timers?.clearAll === 'function') {
                harness.timers.clearAll()
            }
        }
        catch(error) {
            cleanupErrors.push(error)
        }
    }

    if(cleanupErrors.length) {
        const error = new Error(`${cleanupErrors.length} synthetic harness cleanup failure${cleanupErrors.length === 1 ? '' : 's'}`)
        error.causes = cleanupErrors
        throw error
    }
}

async function waitFor(predicate, message, options = {}) {
    const attempts = Number.parseInt(options.attempts, 10) || 20
    const timers = options.timers || null
    const tickMs = Number.parseInt(options.tickMs, 10) || 0

    for(let index = 0; index < attempts; index += 1) {
        const value = await predicate()
        if(value) return value
        await flushAsync(25)
        if(timers) await timers.tick(tickMs)
    }

    throw new Error(message)
}

async function settleWithFakeTimers(promise, timers, steps = [0, 1000, 4000, 5000, 15000, 30000]) {
    let settled = false
    let settledValue
    let settledError

    promise.then(value => {
        settled = true
        settledValue = value
    }, error => {
        settled = true
        settledError = error
    })

    await flushAsync(200)
    if(settledError) throw settledError
    if(settled) return settledValue

    for(const step of steps) {
        await flushAsync(10)
        if(settled) break
        await timers.tick(step)
        if(settled) break
    }

    const longQueueTimerSteps = [10000, 20000, 60000, 180000]
    for(const step of longQueueTimerSteps) {
        if(settled) break
        if(steps.includes(step)) continue
        await flushAsync(10)
        if(settled) break
        await timers.tick(step)
    }

    await flushAsync(50)
    if(settledError) throw settledError
    if(!settled) {
        const pendingTimers = timers && typeof timers.pending === 'function'
            ? timers.pending().slice(0, 10)
            : []
        throw new Error(`fake-timer operation did not settle; pendingTimers=${JSON.stringify(pendingTimers)}`)
    }
    return settledValue
}

// Like settleWithFakeTimers, but advances the clock in small fixed
// increments instead of jumping by large steps, stopping the instant the
// promise settles. Use this when a short internal throttle/backoff wait
// needs to clear without overshooting a longer-delay timer scheduled
// immediately afterward (settleWithFakeTimers' bigger steps would fire both
// in one jump).
async function settleWithFakeTimersInSmallSteps(promise, timers, {stepMs = 50, maxSteps = 60} = {}) {
    let settled = false
    let settledValue
    let settledError
    promise.then(value => {
        settled = true
        settledValue = value
    }, error => {
        settled = true
        settledError = error
    })

    for(let index = 0; index < maxSteps && !settled; index += 1) {
        await flushAsync(5)
        if(settled) break
        await timers.tick(stepMs)
    }

    await flushAsync(20)
    if(settledError) throw settledError
    if(!settled) {
        const pendingTimers = timers && typeof timers.pending === 'function'
            ? timers.pending().slice(0, 10)
            : []
        throw new Error(`fake-timer operation did not settle; pendingTimers=${JSON.stringify(pendingTimers)}`)
    }
    return settledValue
}

function listTabs(browser) {
    return Array.from(browser.__tabs.values())
}

function getStorageSoftFailCounterSnapshot(sw) {
    const counters = sw.state().queueWakeupCounters
    return {
        timedOut: counters['storageUpdate.timedOut'] || 0,
        fallbackReturned: counters['storageUpdate.fallbackReturned'] || 0,
        abandoned: counters['storageUpdate.abandoned'] || 0,
        timeoutBeforeStart: counters['storageUpdate.timeout.beforeStart'] || 0,
        timeoutDuringStorageGet: counters['storageUpdate.timeout.duringStorageGet'] || 0
    }
}

function assertStorageSoftFailCounterDeltaZero(sw, before) {
    const after = getStorageSoftFailCounterSnapshot(sw)
    for(const key of Object.keys(before)) {
        assert.equal(after[key] - before[key], 0, `storage soft-fail delta for ${key}`)
    }
}

function getProgressShardRecord(storage, href) {
    for(const [key, shard] of Object.entries(storage || {})) {
        if(!key.startsWith('mbProfileNukeProgressShard.')) continue
        const record = shard?.records?.[href]
        if(record) return record
    }
    return null
}

// The shard count is declared once, in storageKeys.js (24 Oct).
const {PROFILE_NUKE_PROGRESS_SHARD_COUNT: PROGRESS_SHARD_COUNT_FOR_TESTS} = require('../shared/js/storageKeys')

function getProgressShardKey(href) {
    let hash = 0
    for(let index = 0; index < href.length; index += 1) {
        hash = ((hash * 31) + href.charCodeAt(index)) >>> 0
    }
    return `mbProfileNukeProgressShard.${(hash % PROGRESS_SHARD_COUNT_FOR_TESTS).toString(16).padStart(2, '0')}`
}

function getStoredCoordinatorQueueWal(storage = {}) {
    const hasSegmentedWal = !!storage?.['mbCoordinatorQueueWal.meta']
    const hydrated = hasSegmentedWal
        ? hydrateSegmentedWalStore(storage, {baseKey: 'mbCoordinatorQueueWal'})
        : null
    if(storage?.__syntheticRawQueueWalSeed === true) {
        const store = hydrated?.ok === true ? hydrated.store : storage?.mbCoordinatorQueueWal
        const activeGenerationId = store?.meta?.activeCheckpoint || ''
        const activeSegments = Array.isArray(store?.wal?.[activeGenerationId]?.segments)
            ? store.wal[activeGenerationId].segments.length
            : 0
        if((Number.parseInt(store?.meta?.nextSeq, 10) || 0) <= 1 && activeSegments === 0) {
            return undefined
        }
    }
    if(hydrated?.ok === true) return hydrated.store
    if(storage?.mbCoordinatorQueueWal) return storage.mbCoordinatorQueueWal
    return undefined
}

function isCoordinatorQueueWalPayload(payload = {}) {
    return !!(payload?.mbCoordinatorQueueWal || payload?.['mbCoordinatorQueueWal.meta'])
}

function makeSegmentedQueueWalStorage(queue = {}, segmentCount = 0, options = {}) {
    let store = makePairedCheckpointStore({queue}, {
        createdAt: options.createdAt || 1000,
        nextSeq: 1
    })
    const keys = Object.keys(queue || {})
    const rowKey = options.rowKey || keys[0] || 'synthetic-row'
    for(let index = 0; index < segmentCount; index += 1) {
        store = appendWalRecordsToGeneration(store, [{
            kind: 'map.patch',
            area: 'queue',
            key: rowKey,
            patch: {
                syntheticWalSegmentNo: index
            },
            operationKind: 'synthetic-segment-seed',
            at: (options.createdAt || 1000) + index
        }], {
            segmentId: `synthetic-segment-${index}`
        }).store
    }
    return buildSegmentedWalStoragePayload(store, {
        baseKey: 'mbCoordinatorQueueWal',
        softSwitchAt: 896,
        hardSegmentLimit: 1024,
        updatedAt: options.updatedAt || options.createdAt || 1000
    })
}

function hasQueueWalFixtureStorage(storage = {}) {
    return !!(storage?.mbCoordinatorQueueWal || storage?.['mbCoordinatorQueueWal.meta'])
}

function refreshSyntheticRawQueueWalSeed(storage = {}, now = 1000) {
    if(storage?.__syntheticRawQueueWalSeed !== true) return
    // The worker retires the raw key on every install, update and startup (retireUnusedVersion15StorageKeys, reached from
    // swBootstrap.js), and nothing rebuilds the WAL from a retired raw key. Rebuilding here would replace the base the worker
    // already holds with an empty queue, so the worker's next append would write a fingerprint that disagrees with the
    // stored manifest (docs/queue-storage-layering.md, section 11: no writes outside the worker). The raw key is a source only
    // until the worker retires it.
    if(storage.mbCoordinatorQueue === undefined) return
    const hydrated = hydrateSegmentedWalStore(storage, {baseKey: 'mbCoordinatorQueueWal'})
    const store = hydrated?.ok === true ? hydrated.store : storage?.mbCoordinatorQueueWal
    const activeGenerationId = store?.meta?.activeCheckpoint || ''
    const activeSegments = Array.isArray(store?.wal?.[activeGenerationId]?.segments)
        ? store.wal[activeGenerationId].segments.length
        : 0
    if((Number.parseInt(store?.meta?.nextSeq, 10) || 0) > 1 || activeSegments > 0) return
    // Once the worker has written its own sharded checkpoint, the storage is the worker's state,
    // not the raw fixture. Re-seeding it would roll the checkpoint pointer back on the next read.
    const diskMeta = storage?.['mbCoordinatorQueueWal.meta']
    if(Number.parseInt(diskMeta?.checkpoints?.[diskMeta?.activeCheckpoint]?.shardCount, 10) > 0) return

    Object.assign(storage, makeSegmentedQueueWalStorage(storage.mbCoordinatorQueue || {}, 0, {
        createdAt: now
    }), {
        __syntheticRawQueueWalSeed: true
    })
}

function loadServiceWorkerHarness(options = {}) {
    if(options.seedRawQueueFixtureAsWal === false) {
        return trackServiceWorkerHarness(loadServiceWorkerHarnessBase(options))
    }

    const storage = options.storage && typeof options.storage === 'object'
        ? options.storage
        : options.browser?.__storage && typeof options.browser.__storage === 'object'
            ? options.browser.__storage
            : null
    if(storage?.mbCoordinatorQueue &&
        typeof storage.mbCoordinatorQueue === 'object' &&
        !hasQueueWalFixtureStorage(storage)) {
        const seededStorage = {
            ...storage,
            ...makeSegmentedQueueWalStorage(storage.mbCoordinatorQueue, 0, {
                createdAt: options.now || 1000
            }),
            __syntheticRawQueueWalSeed: true
        }
        if(options.browser?.__storage === storage) {
            Object.assign(storage, seededStorage)
        }
        const harness = trackServiceWorkerHarness(loadServiceWorkerHarnessBase({
            ...options,
            storage: options.browser ? options.storage : seededStorage
        }))
        const originalGet = harness.browser.storage.local.get.bind(harness.browser.storage.local)
        harness.browser.storage.local.get = async defaults => {
            refreshSyntheticRawQueueWalSeed(harness.storage, options.now || 1000)
            return originalGet(defaults)
        }
        return harness
    }

    return trackServiceWorkerHarness(loadServiceWorkerHarnessBase(options))
}

function makeProgressProjectionSeed(href, record = {}) {
    const progressRecord = {
        profileHref: href,
        ...record
    }
    const shardKey = getProgressShardKey(href)
    return {
        mbProfileNukeProgressView: {
            version: 2,
            updatedAt: progressRecord.updatedAt || 1,
            total: 1,
            recordLimit: 1200,
            truncated: false,
            records: {
                [href]: progressRecord
            }
        },
        [shardKey]: {
            version: 1,
            updatedAt: progressRecord.updatedAt || 1,
            records: {
                [href]: progressRecord
            }
        }
    }
}

function getRecoveredCoordinatorQueue(storage = {}) {
    const walStore = getStoredCoordinatorQueueWal(storage)
    if(walStore) {
        const recovered = recoverProjectedState(walStore, [], TEST_QUEUE_WAL_SNAPSHOT_CODEC_OPTIONS)
        const queue = recovered?.projected?.state?.queue || recovered?.state?.queue
        if(queue && typeof queue === 'object') return queue
    }
    return storage?.mbCoordinatorQueue || {}
}

// mbCoordinatorQueueView is no longer persisted to disk (see
// refreshCoordinatorQueueViewForDashboard's own comment in sw.js) -- tests
// that used to read storage.mbCoordinatorQueueView directly for counts/items
// recompute it fresh the same way the dashboard would instead.
function getFreshQueueView(sw, storage = {}) {
    return sw.buildCoordinatorQueueView(getRecoveredCoordinatorQueue(storage), Date.now(), {runs: storage.mbCoordinatorRuns || {}})
}

function hasStorageDefault(defaults = {}, key = '') {
    if(key === 'mbCoordinatorQueueWal') {
        return Object.prototype.hasOwnProperty.call(defaults || {}, 'mbCoordinatorQueueWal') ||
            Object.prototype.hasOwnProperty.call(defaults || {}, 'mbCoordinatorQueueWal.meta')
    }
    return Object.prototype.hasOwnProperty.call(defaults || {}, key)
}

function findStorageGetDefaults(getDefaults = [], keys = []) {
    return getDefaults.find(defaults => keys.every(key => hasStorageDefault(defaults, key))) || null
}

