test('service-worker blocked sweep terminalizes owned blocked profile tab', async () => {
    const href = 'https://www.quora.com/profile/Synthetic-Service-Worker-Blocked-Sweep'
    const runId = 'run-service-worker-blocked-sweep'
    const attemptId = 'attempt-service-worker-blocked-sweep'
    const {browser, storage, sw, timers} = loadServiceWorkerHarness({
        now: 10070,
        storage: {
            mbCoordinatorPaused: false,
            mbCoordinatorQueue: {
                [href]: {
                    ...makeActiveCoordinatorRow({
                        href,
                        runId,
                        attemptId,
                        tabId: 501,
                        now: 10070
                    }),
                    // Matches the legacy progress mirror's blockAttemptedAt
                    // below: a direct block click was already attempted, so
                    // the sweep confirming it below is a really-blocked
                    // outcome, not a pre-existing-block discovery.
                    milestones: {blockAttemptedAt: 10065}
                }
            },
            mbCoordinatorRuns: {
                [runId]: makeCoordinatorRun({href, runId})
            },
            mbCoordinatorEvents: [],
            [LEGACY_PROFILE_PROGRESS_KEY]: {
                [href]: {
                    profileHref: href,
                    actionKind: 'mute-block',
                    status: 'blocking',
                    tabId: 501,
                    attemptId,
                    attemptNumber: 1,
                    blockAttemptedAt: 10065,
                    updatedAt: 10065
                }
            }
        }
    })
    browser.__setNextTabId(501)
    const tab = await browser.tabs.create({url: href, active: true})
    storage.mbCoordinatorQueue[href].tabId = tab.id
    storage[LEGACY_PROFILE_PROGRESS_KEY][href].tabId = tab.id
    const currentAuthorityState = await sw.coordinatorAuthority.hydrate()
    sw.coordinatorAuthority.current().queue[href].tabId = tab.id
    await flushAsync(20)
    sw.__testAddProvisionalQueuedTab(tab.id, {
        profileHref: href,
        coordinatorKey: href,
        requestedUrl: href,
        tabAction: 'nuke',
        actionKind: 'mute-block',
        ownerTabId: 'service-worker-queue-owner',
        runId,
        attemptId,
        attemptNumber: 1,
        openedAt: 10060,
        durableActiveAt: 10065
    })
    browser.tabs.sendMessage = async (tabId, message) => {
        if(message?.action === 'close-if-blocked') {
            return {
                willClose: true,
                resolvedProfileHref: href,
                lastUrl: href
            }
        }
        return {}
    }

    const result = await browser.runtime.sendMessage({
        action: 'sweep-service-worker-blocked-profile-tabs'
    })

    assert.equal(result.owned, 1)
    assert.equal(result.signaled, 1)
    assert.equal(browser.__tabs.has(tab.id), false)
    const archivedRow = await waitFor(
        () => sw.findCompletedWorkRowByKey(href),
        'blocked sweep terminal row did not archive',
        {attempts: 40}
    )
    assert.equal(archivedRow.status, 'succeeded')
    // This sweep only ever fires for a row we already have active (we were
    // directly blocking it ourselves) -- it is a fallback for a missed
    // close-if-blocked confirmation, not a detector of a pre-existing
    // block, so the outcome is 'blocked' (really blocked, counted toward
    // reallyBlocked), not 'already-blocked'. Fixed 2026-09-17: this used to
    // hardcode foundBlockedBeforeQueue: true and land here as
    // 'already-blocked', hiding every sweep-caught block from the
    // reallyBlocked tally.
    assert.equal(archivedRow.outcome, 'blocked')
    assert.equal(sw.state().hasCoordinatorQueueResumeTimeout, true)
    assert.equal(sw.state().hasCoordinatorReconcileTimeout, true)
    assert.equal(storage[LEGACY_PROFILE_PROGRESS_KEY][href].status, 'blocking')
    // The sweep writes the terminal progress record with the queue row (24 Oct), so the progress agrees with the archived row.
    assert.equal(getProgressShardRecord(storage, href)?.status, 'blocked')
    assert.equal(getProgressShardRecord(storage, href)?.blockSucceeded, true)
})

