test('row event queue WAL projection failure does not poison durable acknowledgement', async () => {
    const href = 'https://www.quora.com/profile/Synthetic-Row-Event-Wal-Projection-Failure'
    const runId = 'run-row-event-wal-projection-failure'
    const attemptId = 'attempt-row-event-wal-projection-failure'
    const tabId = 527
    const {browser, storage, sw, timers} = loadServiceWorkerHarness({
        now: 152000,
        storage: {
            mbCoordinatorPaused: false,
            mbCoordinatorQueue: {
                [href]: {
                    ...makeActiveCoordinatorRow({href, runId, attemptId, tabId: null, now: 152000}),
                    status: 'queued',
                    activeAt: 0,
                    tabId: null
                }
            },
            mbCoordinatorRuns: {
                [runId]: makeCoordinatorRun({href, runId})
            },
            mbCoordinatorEvents: [],
            [LEGACY_PROFILE_PROGRESS_KEY]: {
                [href]: {
                    profileHref: href,
                    status: 'queued',
                    runId,
                    actionKind: 'mute-block',
                    attemptId,
                    attemptNumber: 1,
                    updatedAt: 151500
                }
            }
        }
    })
    // 2026-10-01: mbCoordinatorQueueView is no longer part of this write at
    // all (see buildCoordinatorQueueDerivedProjectionPayload's own comment)
    // -- mbCoordinatorContentQueueIndex is still bundled into the same
    // derived-projection save, so failing it exercises the same
    // "projection save failed, durable acknowledgement must still stand"
    // path this test covers.
    const originalSet = browser.storage.local.set.bind(browser.storage.local)
    browser.storage.local.set = async payload => {
        if(payload?.mbCoordinatorContentQueueIndex) {
            return false
        }
        return originalSet(payload)
    }

    const result = await sw.applyCoordinatorRowEvent({
        eventKind: 'queued-progress-milestone',
        profileHref: href,
        patch: {
            status: 'page-ready',
            actionReadyAt: 152010,
            runId,
            tabId,
            actionKind: 'mute-block',
            attemptId,
            attemptNumber: 1
        }
    })

    assert.equal(result.recorded, true)
    assert.equal(result.terminal, false)
    assert.equal(storage.mbCoordinatorQueue[href].status, 'queued')
    assert.ok(getStoredCoordinatorQueueWal(storage))
    assert.equal(storage.mbCoordinatorQueueView, undefined)
    // 601f 1a: the index is no longer written, so its injected failure is never reached and no projection failure is recorded.
    await flushAsync(20)
    assert.equal((await sw.coordinatorAuthority.hydrate()).queue[href].status, 'active')
    assert.equal(sw.state().queueWakeupCounters['coordinatorAuthority.queueWal.projectionFailed'] || 0, 0)
    // 601f 1a: no index write can fail, so no reconcile is scheduled for one.
})

