test('action lease heartbeat is WAL-backed and does not clear unrelated expired lease', async () => {
    const href = 'https://www.quora.com/profile/Synthetic-Lease-Heartbeat'
    const otherHref = 'https://www.quora.com/profile/Synthetic-Lease-Expired-Other'
    const runId = 'run-lease-heartbeat'
    const otherRunId = 'run-lease-expired-other'
    const attemptId = 'attempt-lease-heartbeat'
    const otherAttemptId = 'attempt-lease-expired-other'
    const tabId = 620
    const now = 260000
    const {storage, sw, timers, browser} = loadServiceWorkerHarness({
        now,
        storage: {
            mbCoordinatorPaused: false,
            mbCoordinatorQueue: {
                [href]: {
                    ...makeActiveCoordinatorRow({href, runId, attemptId, tabId, now}),
                    actionLease: {
                        kind: 'profile-menu',
                        actionKind: 'mute-block',
                        profileHref: href,
                        tabId,
                        attemptId,
                        attemptNumber: 1,
                        grantedAt: now - 5000,
                        heartbeatAt: now - 1000,
                        expiresAt: now + 10000,
                        reason: 'test'
                    }
                },
                [otherHref]: {
                    ...makeActiveCoordinatorRow({href: otherHref, runId: otherRunId, attemptId: otherAttemptId, tabId: 621, now}),
                    actionLease: {
                        kind: 'profile-menu',
                        actionKind: 'mute-block',
                        profileHref: otherHref,
                        tabId: 621,
                        attemptId: otherAttemptId,
                        attemptNumber: 1,
                        grantedAt: now - 20000,
                        heartbeatAt: now - 20000,
                        expiresAt: now - 1,
                        reason: 'expired-other'
                    }
                }
            },
            mbCoordinatorRuns: {
                [runId]: makeCoordinatorRun({href, runId}),
                [otherRunId]: makeCoordinatorRun({href: otherHref, runId: otherRunId})
            },
            mbCoordinatorEvents: []
        }
    })

    // The lease holders are live tabs. A lease whose tab is gone is released by the reconcile, as designed.
    browser.__tabs.set(tabId, {id: tabId, windowId: 1, url: href, active: true, status: 'complete'})
    browser.__tabs.set(621, {id: 621, windowId: 1, url: otherHref, active: false, status: 'complete'})

    const result = await sw.heartbeatCoordinatorActionLease({
        profileHref: href,
        attemptId,
        attemptNumber: 1
    }, {
        tab: {id: tabId}
    })

    assert.equal(result.heartbeat, true)
    assert.equal(storage.mbCoordinatorQueue[href].actionLease.heartbeatAt, now - 1000)
    // Checked before any timer runs: the heartbeat writes its own row and leaves the unrelated expired lease alone.
    assert.equal(sw.coordinatorAuthority.current().queue[href].actionLease.heartbeatAt, now)
    assert.equal(sw.coordinatorAuthority.current().queue[otherHref].actionLease.reason, 'expired-other')
    assert.ok(getStoredCoordinatorQueueWal(storage))
    // The queue-view projection save is now deferred (see the
    // deferProjectionSave comment on mutateCoordinatorActionLeaseHeartbeat in
    // sw.js) since a heartbeat never changes anything the view summarizes --
    // tick the deferred setTimeout(0) before reading it back, matching the
    // action-lease-request test's pattern above.
    await timers.tick(0)
    await flushAsync(50)
    assert.equal(getFreshQueueView(sw, storage).counts.active, 2)
    assert.equal(sw.coordinatorAuthority.current().queue[href].actionLease.heartbeatAt, now)

    // The reconcile may release the other row's expired lease after the heartbeat. That is its own record, not the heartbeat's.
    const walRecords = getWalRecordsForGeneration(
        getStoredCoordinatorQueueWal(storage),
        getStoredCoordinatorQueueWal(storage).meta.activeCheckpoint
    )
    const heartbeatRecords = walRecords.filter(record => record.operationKind === 'action-lease-heartbeat')
    assert.equal(heartbeatRecords.length, 1)
    assert.equal(heartbeatRecords[0].key, href)
    assert.ok(walRecords.every(record => record.key !== otherHref || record.operationKind !== 'action-lease-heartbeat'))

    const restarted = loadServiceWorkerHarness({
        now: now + 1000,
        storage
    })
    const hydrated = await restarted.sw.coordinatorAuthority.hydrate()
    assert.equal(hydrated.queue[href].actionLease.heartbeatAt, now)
    assert.deepEqual(
        hydrated.queue[otherHref].actionLease ?? null,
        sw.coordinatorAuthority.current().queue[otherHref].actionLease ?? null
    )
})

test('a resident-fast-path mutation records accurate durable work counts for the no-work-writes metric', async () => {
    // 2026-10-06: recordActiveStorageWorkSnapshot used to only ever get
    // called from inside the ~10 "load" functions (loadCoordinatorCurrentAuthorityState
    // and siblings) -- a mutation that instead took applyLocked's resident-
    // projection fast path (no currentAuthorityState supplied, the common
    // case for call sites that don't bother pre-resolving one -- e.g.
    // recoverExhaustedRolledBackQueuedCoordinatorItem) never recorded a
    // snapshot at all, so the active storage context's durableActiveRows/
    // durableQueuedRows stayed at their 0 default and
    // recordStorageIdleChurnCounters misclassified the write as "no durable
    // work" / "no runtime work" regardless of how busy the queue actually
    // was. This proves the fix: a mutation reached via the resident fast
    // path, with other real queued/active rows present, no longer trips
    // storageUpdate.noDurableWork.
    const mutatedHref = 'https://www.quora.com/profile/Synthetic-No-Work-Writes-Mutated'
    const otherActiveHref = 'https://www.quora.com/profile/Synthetic-No-Work-Writes-Other-Active'
    const otherQueuedHref = 'https://www.quora.com/profile/Synthetic-No-Work-Writes-Other-Queued'
    const runId = 'run-no-work-writes-accounting'
    const attemptId = 'attempt-no-work-writes-mutated'
    const now = 266000
    const {sw, storage} = loadServiceWorkerHarness({
        now,
        storage: {
            mbCoordinatorPaused: false,
            mbCoordinatorQueue: {
                [mutatedHref]: makeActiveCoordinatorRow({href: mutatedHref, runId, attemptId, tabId: 640, now}),
                [otherActiveHref]: makeActiveCoordinatorRow({href: otherActiveHref, runId, attemptId: 'attempt-no-work-writes-other-active', tabId: 641, now}),
                [otherQueuedHref]: makeQueuedCoordinatorRow({href: otherQueuedHref, runId, attemptId: 'attempt-no-work-writes-other-queued', now})
            },
            mbCoordinatorRuns: {
                [runId]: makeCoordinatorRun({href: mutatedHref, runId})
            },
            mbCoordinatorEvents: [],
            [LEGACY_PROFILE_PROGRESS_KEY]: {}
        }
    })

    await sw.coordinatorAuthority.hydrate()

    const mutationResult = await sw.enqueueSpaceFeedStorageUpdate(() => sw.coordinatorAuthority.applyWithinStorageUpdate({
        operationKind: 'row-event-progress-milestone',
        rowKey: mutatedHref,
        reason: 'ordinaryMutation',
        // Deliberately no currentAuthorityState/authorityState/lockedProjection
        // -- forces applyLocked's resident-projection fast path, the one
        // that used to skip recordActiveStorageWorkSnapshot entirely.
        mutate(current) {
            return {
                ...current,
                updatedAt: now + 100,
                milestones: {
                    ...(current.milestones || {}),
                    actionReadyAt: now + 100
                }
            }
        }
    }))

    assert.equal(mutationResult.durable, true, JSON.stringify(mutationResult))
    assert.equal(sw.coordinatorAuthority.current().queue[mutatedHref].updatedAt, now + 100)
    assert.equal(sw.state().queueWakeupCounters['storageUpdate.noDurableWork'] || 0, 0)
})

test('action lease heartbeat never rebuilds the content-queue-index/source-index projections', async () => {
    // Regression for the entropy-reduction Phase 7 cost-multiplier finding
    // (2026-09-12): every authority row mutation used to fall through to
    // buildCoordinatorQueueDerivedProjectionPayload by default -- a full
    // O(queue) rebuild of the queue view AND the content-queue-index AND all
    // content-source-index shards -- synchronously, on the WAL-write path.
    // Action-lease heartbeats fire every QUEUED_ACTION_HEARTBEAT_MS (5s,
    // content.js) for as long as an item stays active, making them by far
    // the highest-frequency authority mutation, yet a heartbeat only ever
    // touches actionLease bookkeeping, never anything the content-queue-index
    // or source-index shards summarize. This asserts the fix: those two
    // projections are left completely untouched (same reference) by a
    // heartbeat, synchronously AND after its deferred queue-view save fires,
    // while the queue view and the WAL row itself are still updated.
    const href = 'https://www.quora.com/profile/Synthetic-Lease-Heartbeat-Cost'
    const runId = 'run-lease-heartbeat-cost'
    const attemptId = 'attempt-lease-heartbeat-cost'
    const tabId = 623
    const now = 260500
    const sentinelContentQueueIndex = {version: 2, updatedAt: now - 1000, total: 0, indexed: 0, itemLimit: 500, truncated: false, items: []}
    const {storage, sw, timers} = loadServiceWorkerHarness({
        now,
        storage: {
            mbCoordinatorPaused: false,
            mbCoordinatorQueue: {
                [href]: {
                    ...makeActiveCoordinatorRow({href, runId, attemptId, tabId, now}),
                    actionLease: {
                        kind: 'profile-menu',
                        actionKind: 'mute-block',
                        profileHref: href,
                        tabId,
                        attemptId,
                        attemptNumber: 1,
                        grantedAt: now - 5000,
                        heartbeatAt: now - 1000,
                        expiresAt: now + 10000,
                        reason: 'test'
                    }
                }
            },
            mbCoordinatorRuns: {
                [runId]: makeCoordinatorRun({href, runId})
            },
            mbCoordinatorEvents: [],
            mbCoordinatorContentQueueIndex: sentinelContentQueueIndex
        }
    })

    const result = await sw.heartbeatCoordinatorActionLease({
        profileHref: href,
        attemptId,
        attemptNumber: 1
    }, {
        tab: {id: tabId}
    })

    assert.equal(result.heartbeat, true)
    assert.equal(sw.coordinatorAuthority.current().queue[href].actionLease.heartbeatAt, now)
    assert.ok(getStoredCoordinatorQueueWal(storage))
    // A rebuild would call buildCoordinatorContentQueueIndex(queue, now) and
    // stamp the fresh `now` (260500) as updatedAt -- the storage mock clones
    // on write/read, so reference equality can't be used here; the stale
    // updatedAt from the sentinel is the tell.
    assert.equal(storage.mbCoordinatorContentQueueIndex.updatedAt, now - 1000)

    await timers.tick(0)
    await flushAsync(50)

    assert.equal(getFreshQueueView(sw, storage).counts.active, 1)
    assert.equal(storage.mbCoordinatorContentQueueIndex.updatedAt, now - 1000)
})

