test('concurrent terminal projection saves do not regress newer terminal progress', async () => {
    const hrefA = 'https://www.quora.com/profile/Synthetic-Terminal-Concurrent-A'
    const hrefB = 'https://www.quora.com/profile/Synthetic-Terminal-Concurrent-B'
    const runIdA = 'run-terminal-concurrent-a'
    const runIdB = 'run-terminal-concurrent-b'
    const attemptIdA = 'attempt-terminal-concurrent-a'
    const attemptIdB = 'attempt-terminal-concurrent-b'
    const {storage, sw} = loadServiceWorkerHarness({
        now: 255000,
        storage: {
            mbCoordinatorPaused: false,
            mbCoordinatorQueue: {
                [hrefA]: makeActiveCoordinatorRow({href: hrefA, runId: runIdA, attemptId: attemptIdA, tabId: 514, now: 255000}),
                [hrefB]: makeActiveCoordinatorRow({href: hrefB, runId: runIdB, attemptId: attemptIdB, tabId: 515, now: 255000})
            },
            mbCoordinatorRuns: {
                [runIdA]: makeCoordinatorRun({href: hrefA, runId: runIdA}),
                [runIdB]: makeCoordinatorRun({href: hrefB, runId: runIdB})
            },
            mbCoordinatorEvents: [],
            [LEGACY_PROFILE_PROGRESS_KEY]: {
                [hrefA]: {
                    profileHref: hrefA,
                    status: 'blocking',
                    runId: runIdA,
                    tabId: 514,
                    actionKind: 'mute-block',
                    attemptId: attemptIdA,
                    attemptNumber: 1,
                    updatedAt: 254500
                },
                [hrefB]: {
                    profileHref: hrefB,
                    status: 'blocking',
                    runId: runIdB,
                    tabId: 515,
                    actionKind: 'mute-block',
                    attemptId: attemptIdB,
                    attemptNumber: 1,
                    updatedAt: 254500
                }
            }
        }
    })

    const firstPromise = sw.recordCoordinatorJobProgress(hrefA, {
        status: 'blocked',
        blockSucceeded: true,
        blockedAt: 255100,
        terminalAt: 255100,
        actionKind: 'mute-block',
        runId: runIdA,
        tabId: 514,
        attemptId: attemptIdA,
        attemptNumber: 1
    }, {
        expectTerminal: true,
        senderTabId: 514
    })
    const secondPromise = sw.recordCoordinatorJobProgress(hrefB, {
        status: 'blocked',
        blockSucceeded: true,
        blockedAt: 255200,
        terminalAt: 255200,
        actionKind: 'mute-block',
        runId: runIdB,
        tabId: 515,
        attemptId: attemptIdB,
        attemptNumber: 1
    }, {
        expectTerminal: true,
        senderTabId: 515
    })

    const [first, second] = await Promise.all([firstPromise, secondPromise])

    assert.equal(first.recorded, true)
    assert.equal(first.terminal, true)
    assert.equal(second.recorded, true)
    assert.equal(second.terminal, true)
    assert.equal(storage.mbCoordinatorQueue[hrefA].status, 'active')
    assert.equal(storage.mbCoordinatorQueue[hrefB].status, 'active')
    const archivedA = await waitFor(
        () => sw.findCompletedWorkRowByKey(hrefA),
        'hrefA did not archive',
        {attempts: 40}
    )
    const archivedB = await waitFor(
        () => sw.findCompletedWorkRowByKey(hrefB),
        'hrefB did not archive',
        {attempts: 40}
    )
    assert.equal(archivedA.status, 'succeeded')
    assert.equal(archivedB.status, 'succeeded')
    // Both rows archived out of .queue/queueView entirely.
    assert.equal(storage.mbCoordinatorQueueView?.counts.succeeded, undefined)
    const walRecords = getWalRecordsForGeneration(
        getStoredCoordinatorQueueWal(storage),
        getStoredCoordinatorQueueWal(storage).meta.activeCheckpoint
    )
    // 6, not 2: each row's own terminal-progress record plus its own
    // fire-and-forget archive batch (queue removal + completed-area add).
    assert.equal(walRecords.length, 6)
    assert.equal(getStoredCoordinatorQueueWal(storage).meta.nextSeq, 7)

    await waitFor(
        () => getProgressShardRecord(storage, hrefA)?.status === 'blocked' &&
            getProgressShardRecord(storage, hrefB)?.status === 'blocked',
        'concurrent terminal projection saves regressed one progress projection record',
        {attempts: 40}
    )

    assert.equal(getProgressShardRecord(storage, hrefA).status, 'blocked')
    assert.equal(getProgressShardRecord(storage, hrefB).status, 'blocked')
    assert.equal(getProgressShardRecord(storage, hrefA).attemptId, attemptIdA)
    assert.equal(getProgressShardRecord(storage, hrefB).attemptId, attemptIdB)
})

test('terminal job progress acknowledges durable terminal queue before projection save timeout', async () => {
    const href = 'https://www.quora.com/profile/Synthetic-Terminal-Compatibility-Timeout'
    const runId = 'run-terminal-compatibility-timeout'
    const attemptId = 'attempt-terminal-compatibility-timeout'
    const tabId = 505
    const {browser, storage, sw, timers} = loadServiceWorkerHarness({
        now: 270000,
        storage: {
            mbCoordinatorPaused: false,
            mbCoordinatorQueue: {
                [href]: makeActiveCoordinatorRow({href, runId, attemptId, tabId, now: 270000})
            },
            mbCoordinatorRuns: {
                [runId]: makeCoordinatorRun({href, runId})
            },
            mbCoordinatorEvents: [],
            [LEGACY_PROFILE_PROGRESS_KEY]: {
                [href]: {
                    profileHref: href,
                    status: 'blocking',
                    runId,
                    tabId,
                    actionKind: 'mute-block',
                    attemptId,
                    attemptNumber: 1,
                    updatedAt: 269500
                }
            }
        }
    })
    const stalledSet = deferred()
    const originalSet = browser.storage.session.set.bind(browser.storage.session)
    browser.storage.session.set = async payload => {
        if(payload?.mbProfileNukeProgressView ||
            Object.keys(payload || {}).some(key => key.startsWith('mbProfileNukeProgressShard.'))) {
            return stalledSet.promise
        }
        return originalSet(payload)
    }

    const result = await sw.recordCoordinatorJobProgress(href, {
        status: 'blocked',
        blockSucceeded: true,
        blockedAt: 270100,
        terminalAt: 270100,
        actionKind: 'mute-block',
        runId,
        tabId,
        attemptId,
        attemptNumber: 1
    }, {
        expectTerminal: true,
        senderTabId: tabId
    })

    assert.equal(result.recorded, true)
    assert.equal(result.terminal, true)
    assert.equal(storage.mbCoordinatorQueue[href].status, 'active')
    assert.equal((await sw.findCompletedWorkRowByKey(href))?.status, 'succeeded')
    assert.equal(storage.mbCoordinatorQueueView?.counts.succeeded, undefined)
    assert.equal(storage[LEGACY_PROFILE_PROGRESS_KEY][href].status, 'blocking')

    await timers.tick(sw.state().constants.QUEUE_CRITICAL_STORAGE_UPDATE_TIMEOUT_MS + 1000)
    await flushAsync(20)

    assert.equal(sw.state().queueWakeupCounters['terminalProgress.projectionSaveFailed'] || 0, 1)
    assert.ok(
        sw.state().hasCoordinatorReconcileTimeout ||
            (sw.state().queueWakeupCounters['reconcile.deferredBeforeQuora'] || 0) >= 1
    )
})

