test('late successful terminal progress does not overwrite profile redirect mismatch skip', async () => {
    const href = 'https://www.quora.com/profile/Synthetic-Redirect-Source'
    const redirectedHref = 'https://www.quora.com/profile/Synthetic-Redirect-Destination'
    const runId = 'run-profile-redirect-mismatch-late-progress'
    const attemptId = 'attempt-profile-redirect-mismatch-late-progress'
    const tabId = 507
    const {browser, sw, storage, timers} = loadServiceWorkerHarness({
        now: 411500,
        storage: {
            mbCoordinatorPaused: false,
            mbCoordinatorQueue: {
                [href]: makeActiveCoordinatorRow({href, runId, attemptId, tabId, now: 411500})
            },
            mbCoordinatorRuns: {
                [runId]: makeCoordinatorRun({href, runId})
            },
            mbCoordinatorEvents: [],
            [LEGACY_PROFILE_PROGRESS_KEY]: {
                [href]: {
                    profileHref: href,
                    status: 'tab-opening',
                    runId,
                    tabId,
                    tabOpenedAt: 411500,
                    updatedAt: 411500,
                    actionKind: 'mute-block',
                    attemptId,
                    attemptNumber: 1
                }
            }
        }
    })
    await sw.coordinatorAuthority.hydrate()
    browser.__tabs.set(tabId, {
        id: tabId,
        windowId: 1,
        url: redirectedHref,
        active: true,
        status: 'complete'
    })
    sw.__testAddProvisionalQueuedTab(tabId, {
        profileHref: href,
        coordinatorKey: href,
        requestedUrl: href,
        tabAction: 'nuke',
        actionKind: 'mute-block',
        runId,
        ownerTabId: 'service-worker-queue-owner',
        attemptId,
        attemptNumber: 1,
        openedAt: 411500
    })

    await browser.tabs.onUpdated.emit(tabId, {
        status: 'complete',
        url: redirectedHref
    }, {
        id: tabId,
        windowId: 1,
        url: redirectedHref,
        status: 'complete'
    })
    await flushAsync(20)
    await timers.tick(1000)
    await flushAsync(20)

    // Same race as the sibling "skipped and closed" test above: the row can
    // archive out of .queue within this same poll budget, so capture the
    // terminal row at the moment it's seen instead of re-reading it after.
    const terminalRow = await waitFor(
        async () => {
            const authorityRow = sw.coordinatorAuthority.current().queue[href]
            if(authorityRow?.status === 'skipped') return authorityRow
            const recoveredRow = getRecoveredCoordinatorQueue(storage)[href]
            if(recoveredRow?.status === 'skipped') return recoveredRow
            // Archived out of the live queue in the same tick it is written, so the completed area is where it is seen.
            const completedRow = await sw.findCompletedWorkRowByKey(href)
            if(completedRow?.status === 'skipped') return completedRow
            return null
        },
        'profile redirect mismatch authority row was not terminalized before late progress',
        {timers, attempts: 20, tickMs: 100}
    )
    assert.equal(terminalRow?.status, 'skipped')
    assert.equal(terminalRow?.outcome, 'profile-redirect-mismatch')

    const lateResult = await browser.runtime.sendMessage({
        action: 'record-job-terminal',
        profileHref: href,
        patch: {
            status: 'already-blocked',
            blockSucceeded: true,
            foundBlockedBeforeQueue: true,
            blockedAt: 411700,
            terminalAt: 411700,
            updatedAt: 411700,
            actionKind: 'mute-block',
            runId,
            tabId,
            attemptId,
            attemptNumber: 1
        },
        attemptId,
        attemptNumber: 1
    }, {
        tab: {id: tabId, url: redirectedHref, windowId: 1}
    })

    // The row already archived out of .queue/the recovered WAL queue as
    // 'skipped' before this late message arrives (see the waitFor above), so
    // the late-arriving "already-blocked" progress -- which would have
    // wrongly overwritten the redirect-mismatch skip if it were applied --
    // no longer finds a resident row to apply to at all. Either way, the
    // late message must not be recorded as a successful terminal outcome,
    // and the archived row must still show the original skip/outcome.
    assert.equal(lateResult.recorded, false)
    assert.equal(lateResult.terminal, false)
    assert.equal(sw.coordinatorAuthority.current().queue[href], undefined)
    assert.equal(getRecoveredCoordinatorQueue(storage)[href], undefined)
    const archivedRow = await sw.findCompletedWorkRowByKey(href)
    assert.equal(archivedRow?.status, 'skipped')
    assert.equal(archivedRow?.outcome, 'profile-redirect-mismatch')
    assert.equal(getProgressShardRecord(storage, href).status, 'profile-unavailable')
    assert.equal(getProgressShardRecord(storage, href).resolvedProfileHref, redirectedHref)
})

