test('abandoned storage update suppresses late reads and writes', async () => {
    const href = 'https://www.quora.com/profile/Abandoned-Read-Keeps-Authority'
    const duplicateTabId = 1795
    const secondDuplicateTabId = 2795
    const {browser, sw, storage, timers} = loadServiceWorkerHarness({
        now: 1000,
        storage: {
            mbCoordinatorQueue: {
                [href]: {
                    id: 'abandoned-read-row',
                    status: 'queued',
                    targetProfileHref: href,
                    updatedAt: 1000
                }
            }
        }
    })
    const gate = deferred()
    const observed = deferred()

    const updateResult = sw.enqueueSpaceFeedStorageUpdate(async () => {
        await gate.promise
        try {
            const stored = await sw.metricStorageGet({mbCoordinatorQueue: {}})
            const saved = await sw.metricStorageSet({mbSyntheticLateWrite: true})
            observed.resolve({stored, saved, error: ''})
            return {done: true}
        }
        catch(error) {
            observed.resolve({stored: null, saved: 'not-run', error: error?.message || `${error || ''}`})
            throw error
        }
    }, {
        timeoutMs: 1000,
        failureValue: {timedOut: true}
    })

    await flushAsync(20)
    await timers.tick(1000)
    assert.deepEqual(await updateResult, {timedOut: true})

    gate.resolve()
    await flushAsync(50)
    const result = await observed.promise

    assert.equal(result.stored, null)
    assert.equal(result.saved, 'not-run')
    assert.match(result.error, /abandoned storage update suppressed after storageGet/)
    assert.equal(storage.mbSyntheticLateWrite, undefined)
    assert.equal(sw.state().queueWakeupCounters['storageUpdate.lateWriteSuppressed'], 1)
    await waitFor(
        () => sw.state().abandonedSpaceFeedStorageUpdates === 0,
        'abandoned storage update did not finish cleanup',
        {timers, attempts: 20, tickMs: 0}
    )
})

test('segmented queue WAL authority read skips obsolete monolithic WAL blob', async () => {
    const href = 'https://www.quora.com/profile/Segmented-No-Legacy-Read'
    const segmented = makeSegmentedQueueWalStorage({
        [href]: {
            id: 'segmented-no-legacy-read-row',
            status: 'queued',
            targetProfileHref: href,
            serviceWorkerOwned: true,
            executorOwner: 'service-worker',
            updatedAt: 1000
        }
    }, 1)
    const {browser, sw} = loadServiceWorkerHarness({
        now: 1000,
        storage: {
            mbCoordinatorQueue: {},
            mbCoordinatorQueueWal: {
                meta: {legacyBlobShouldNotBeRead: true},
                checkpoints: {},
                wal: {}
            },
            ...segmented
        }
    })
    const getCalls = []
    const originalGet = browser.storage.local.get.bind(browser.storage.local)
    browser.storage.local.get = async defaults => {
        getCalls.push(defaults)
        return originalGet(defaults)
    }

    const accounting = await sw.getCoordinatorQueueAccounting({reason: 'synthetic'})

    assert.equal(accounting.recovered.total, 1)
    assert.equal(accounting.recovered.counts.queued, 1)
    assert.equal(accounting.wal.recovered, true)
    assert.equal(
        getCalls.some(defaults => defaults &&
            typeof defaults === 'object' &&
            Object.prototype.hasOwnProperty.call(defaults, 'mbCoordinatorQueueWal')),
        false
    )
    assert.ok(getCalls.some(defaults => defaults?.['mbCoordinatorQueueWal.meta'] === null))
    assert.ok(getCalls.some(defaults => defaults?.['mbCoordinatorQueueWal.checkpoint.A'] === null))
})

test('WAL storage can seed compact dashboard queue view without dashboard full read', async () => {
    const hrefs = Array.from({length: 90}, (_, index) => `https://www.quora.com/profile/Legacy-View-${index}`)
    const queue = Object.fromEntries(hrefs.map((href, index) => [
        href,
        {
            id: `legacy-${index}`,
            status: index < 4 ? 'queued' : 'succeeded',
            targetProfileHref: href,
            queuedAt: 1000 + index,
            updatedAt: 2000 + index,
            terminalAt: index < 4 ? 0 : 3000 + index
        }
    ]))
    const {sw, storage} = loadServiceWorkerHarness({
        now: 1000,
        storage: {
            mbCoordinatorQueue: queue
        }
    })

    const result = await sw.refreshCoordinatorQueueViewForDashboard('test')

    assert.equal(result.refreshed, true)
    assert.equal(result.total, 90)
    assert.equal(result.view.total, 90)
    // The list holds the four live (queued) rows; the 86 finished rows are counted in the total and the counts, not listed.
    assert.equal(result.view.items.length, 4)
    assert.ok(result.view.items.every(item => item.status === 'queued'), 'only live rows are listed')
    assert.equal(result.view.itemLimit, 4)
    assert.equal(result.view.truncated, false)
    assert.equal(result.view.counts.queued, 4)
    // mbCoordinatorQueueView is no longer persisted to disk -- see
    // refreshCoordinatorQueueViewForDashboard's own comment -- so the
    // "without dashboard full read" claim in this test's name is now true of
    // every call, not just this seeded-from-WAL one; nothing writes the raw
    // queue blob either.
    assert.equal(storage.mbCoordinatorQueueView, undefined)
    assert.deepEqual(storage.mbCoordinatorQueue, queue)

    const counters = sw.state().queueWakeupCounters
    assert.ok((counters['storagePayload.read.queueWal.bytes'] || 0) > 0)
    assert.equal(counters['storagePayload.read.queue.bytes'], undefined)
    assert.equal(counters['storagePayload.write.queueView.bytes'], undefined)
    // The first refresh hydrates (its read is labelled currentAuthority.load) and is then answered from the resident
    // state, so the queueView.test path sees no storage read. Was 1 before the readers used the resident state.
    assert.equal(counters['storagePayload.read.path.queueView.test.calls'], undefined)
})

test('dashboard queue view refresh never writes mbCoordinatorQueueView to storage', async () => {
    // 2026-10-01: mbCoordinatorQueueView's disk copy was removed entirely
    // (see refreshCoordinatorQueueViewForDashboard's own comment) -- open
    // pages get it exclusively through this function's return value and the
    // dashboard-notify broadcast, so every poll is a no-write, no-throttle
    // computation and the returned total is always immediately accurate.
    const href = 'https://www.quora.com/profile/Synthetic-Unchanged-View'
    const {sw, storage} = loadServiceWorkerHarness({
        now: 1000,
        storage: {
            mbCoordinatorQueue: {
                [href]: makeQueuedCoordinatorRow({href, now: 1000})
            }
        }
    })

    const first = await sw.refreshCoordinatorQueueViewForDashboard('poll')
    assert.equal(first.total, 1)
    assert.equal(sw.state().queueWakeupCounters['storagePayload.write.path.queueView.poll.calls'], undefined)
    assert.equal(storage.mbCoordinatorQueueView, undefined)

    // The second queued row is written through the worker's own door (persistCoordinator), not a raw storage write:
    // coordinator storage is the worker's to write (P1), so the row is added the way an enqueue adds it.
    await sw.coordinatorAuthority.persistCoordinator({
        results: [{
            operationKind: 'synthetic-second-queued-row',
            rowKey: `${href}-2`,
            accepted: true,
            changed: true,
            durable: true,
            reason: 'persisted',
            previousRow: null,
            nextRow: makeQueuedCoordinatorRow({href: `${href}-2`, now: 1000}),
            terminal: false
        }]
    }, {
        operationKind: 'synthetic-second-queued-row',
        reason: 'ordinaryMutation'
    })
    const second = await sw.refreshCoordinatorQueueViewForDashboard('poll')
    assert.equal(second.total, 2)
    assert.equal(sw.state().queueWakeupCounters['storagePayload.write.path.queueView.poll.calls'], undefined)
    assert.equal(storage.mbCoordinatorQueueView, undefined)
})

test('dashboard queue view refresh omits an archived terminal row whose run is no longer known', async () => {
    // Runs are worked out from the queue rows, so a live row always has its run. The completed-work log keeps the rows that were
    // archived, and the view keeps one of those only when its run is still known. This row's run is in neither the queue nor the runs.
    const staleHref = 'https://www.quora.com/profile/Synthetic-Compact-Stale-Run-Terminal'
    const liveHref = 'https://www.quora.com/profile/Synthetic-Compact-Live-Run-Terminal'
    const pendingHref = 'https://www.quora.com/profile/Synthetic-Compact-Missing-Run-Pending'
    const staleRunId = 'run-compact-stale-terminal'
    const liveRunId = 'run-compact-live-terminal'
    const pendingRunId = 'run-compact-missing-pending'
    const {sw, storage} = loadServiceWorkerHarness({
        now: 2000,
        storage: {
            mbCoordinatorPaused: false,
            ...makeCompletedWalStoragePayload({
                queue: {
                    [liveHref]: {
                        ...makeQueuedCoordinatorRow({
                            href: liveHref,
                            runId: liveRunId,
                            attemptId: 'attempt-compact-live-terminal',
                            now: 1001
                        }),
                        status: 'failed',
                        outcome: 'timeout',
                        error: 'Queued tab active transition failed after exhausting retry budget',
                        terminalAt: 1600,
                        updatedAt: 1600
                    },
                    [pendingHref]: makeQueuedCoordinatorRow({
                        href: pendingHref,
                        runId: pendingRunId,
                        attemptId: 'attempt-compact-missing-pending',
                        now: 1002
                    })
                },
                completed: {
                    [staleHref]: makeArchivedCoordinatorRow({href: staleHref, runId: staleRunId, attemptId: 'attempt-compact-stale-terminal', terminalAt: 1500})
                }
            }),
            mbCoordinatorEvents: [],
            [LEGACY_PROFILE_PROGRESS_KEY]: {}
        }
    })

    const result = await sw.refreshCoordinatorQueueViewForDashboard('pruned-terminal-runs')

    assert.equal(result.refreshed, true)
    assert.equal(result.total, 2)
    assert.equal(result.view.total, 2)
    assert.equal(result.view.counts.failed, 1)
    assert.equal(result.view.counts.queued, 1)
    assert.equal(result.view.counts.succeeded || 0, 0)
    assert.equal(result.view.items.some(item => item.storageKey === staleHref), false)
    assert.equal(result.view.items.some(item => item.storageKey === liveHref), true)
    assert.equal(result.view.items.some(item => item.storageKey === pendingHref), true)
    assert.equal(storage.mbCoordinatorQueueView, undefined)
})

