test('content-page state falls back for source-matched rows outside truncated queue index', async () => {
    const searchUrl = 'https://www.quora.com/search?q=SEO&type=profile'
    const targetHref = 'https://www.quora.com/profile/Seo-Outside-Index'
    const queue = {}

    for(let index = 0; index < 1200; index += 1) {
        const href = `https://www.quora.com/profile/Indexed-${index}`
        const item = {
            id: `indexed-${index}`,
            status: 'queued',
            serviceWorkerOwned: true,
            executorOwner: 'service-worker',
            targetProfileHref: href,
            queuedAt: 10000 + index,
            updatedAt: 10000 + index
        }
        queue[href] = item
    }
    queue[targetHref] = {
        id: 'outside-index',
        status: 'queued',
        serviceWorkerOwned: true,
        executorOwner: 'service-worker',
        targetProfileHref: targetHref,
        queuedAt: 1,
        updatedAt: 1,
        source: {
            type: 'profile-search',
            pageUrl: searchUrl,
            searchQuery: 'SEO',
            sourceLabel: 'Search: SEO'
        }
    }

    const {browser, sw, storage, timers} = loadServiceWorkerHarness({
        storage: {
            mbProfileNukeProgressView: {
                version: 2,
                updatedAt: 20,
                total: 0,
                recordLimit: 1200,
                truncated: false,
                records: {}
            }
        }
    })
    await sw.coordinatorAuthority.hydrate()
    assert.equal(sw.coordinatorAuthority.seedResidentProjection({queue}), true)

    assert.equal(derivedContentQueueIndex(sw).truncated, true)
    assert.equal(
        derivedContentQueueIndex(sw).items.some(item => item.storageKey === targetHref),
        false
    )
    await activateQuoraRuntime(browser, searchUrl)
    await flushAsync(20)
    const beforeCounters = {
        queueFallbackCalls: sw.state().queueWakeupCounters['storagePayload.read.path.contentPageState.queueFallback.truncated.calls'] || 0,
        rebuildCalls: sw.state().queueWakeupCounters['storagePayload.read.path.contentPageState.rebuild.missing-projection.calls'] || 0,
        sourceIndexReadBytes: sw.state().queueWakeupCounters['storagePayload.read.contentSourceIndex.bytes'] || 0
    }

    const result = await browser.runtime.sendMessage({
        action: 'get-content-page-coordinator-state',
        pageType: 'profile-search',
        sourcePageUrl: searchUrl,
        searchQuery: 'SEO',
        profileHrefs: []
    })

    assert.equal(result.queueRows, 1)
    assert.equal(result.coordinatorQueue[targetHref].status, 'queued')

    const counters = sw.state().queueWakeupCounters
    assert.equal(
        counters['storagePayload.read.path.contentPageState.queueFallback.truncated.calls'] || 0,
        beforeCounters.queueFallbackCalls
    )
    assert.equal(
        counters['storagePayload.read.path.contentPageState.rebuild.missing-projection.calls'] || 0,
        beforeCounters.rebuildCalls
    )
    // 601f 1a: the source index is derived from the resident queue, so the page reads no source-index bytes from storage.
    assert.equal(counters['storagePayload.read.contentSourceIndex.bytes'] || 0, beforeCounters.sourceIndexReadBytes)
})

test('content-page projection rebuild uses WAL terminal authority over stale raw active queue', async () => {
    const href = 'https://www.quora.com/profile/Content-Wal-Terminal-Stale-Raw'
    const runId = 'run-content-wal-terminal-stale-raw'
    const attemptId = 'attempt-content-wal-terminal-stale-raw'
    const tabId = 718
    const {browser, storage, sw} = loadServiceWorkerHarness({
        now: 525000,
        storage: {
            mbCoordinatorPaused: false,
            mbCoordinatorQueue: {
                [href]: makeActiveCoordinatorRow({href, runId, attemptId, tabId, now: 525000})
            },
            mbCoordinatorRuns: {
                [runId]: makeCoordinatorRun({href, runId})
            },
            mbCoordinatorEvents: [],
            [LEGACY_PROFILE_PROGRESS_KEY]: {
                [href]: {
                    profileHref: href,
                    status: 'blocking',
                    runId,
                    tabId,
                    actionKind: 'mute-block',
                    attemptId,
                    attemptNumber: 1,
                    updatedAt: 524500
                }
            }
        }
    })

    const terminal = await sw.recordCoordinatorJobProgress(href, {
        status: 'blocked',
        blockSucceeded: true,
        blockedAt: 525100,
        terminalAt: 525100,
        actionKind: 'mute-block',
        runId,
        tabId,
        attemptId,
        attemptNumber: 1
    }, {
        expectTerminal: true,
        senderTabId: tabId
    })

    assert.equal(terminal.recorded, true)
    assert.equal(terminal.terminal, true)
    assert.equal(storage.mbCoordinatorQueue[href].status, 'active')
    assert.equal((await sw.findCompletedWorkRowByKey(href))?.status, 'succeeded')

    for(const key of Object.keys(storage)) {
        if(key === 'mbCoordinatorContentQueueIndex' || key.startsWith('mbCoordinatorContentSourceIndex.')) {
            delete storage[key]
        }
    }

    const result = await browser.runtime.sendMessage({
        action: 'get-content-page-coordinator-state',
        pageType: 'profile-search',
        profileHrefs: [href]
    })

    assert.equal(result.queueRows, 0)
    assert.equal(result.coordinatorQueue[href], undefined)
    // The row archived out of the live/WAL-recovered queue entirely (it's a
    // content-script-facing index of pending work, not a history view), so
    // the rebuilt index has nothing left to count.
    assert.equal(derivedContentQueueIndex(sw).total, 0)
    assert.equal(derivedContentQueueIndex(sw).indexed, 0)
})

function makeRebuildQueuedRow(href = '') {
    return {
        id: `rebuild-queued-${href}`,
        status: 'queued',
        serviceWorkerOwned: true,
        executorOwner: 'service-worker',
        targetProfileHref: href,
        queuedAt: 10,
        updatedAt: 10
    }
}

function isProfileNukeProgressProjectionKey(key = '') {
    return key === 'mbProfileNukeProgressView' || key.startsWith('mbProfileNukeProgressShard.')
}

