test('createOwnedTabInQueuedWorkerActionSurface serializes two overlapping opens into one tab', async () => {
    // 2026-09-29: fillQueuedTabsOnce's while-loop and planQueuedTabExecutorAction
    // are independent call chains that can each decide a worker-window slot
    // is free and both call in here before either one's tab actually exists
    // -- every capacity counter either one consults is a snapshot, so no
    // amount of fixing those counters closes the gap between two genuinely
    // concurrent callers. Confirmed live twice (Space-Cowboy-208/
    // Elon-Musk-6832; Normal-Guy-Henry/Peaches-and-Cream-67): two tabs
    // opened a few hundred ms apart into the single-tab worker window. The
    // fix is a real lock plus a live re-check against this mechanism's own
    // tracked tabs, not another counter -- this test calls the function
    // twice without awaiting the first, the way two overlapping callers
    // would, and checks only one tab actually gets created.
    const {sw, timers} = loadServiceWorkerHarness({now: 4000})
    const makeAction = href => ({
        ownerTabId: 'service-worker-queue-owner',
        actionKind: 'mute-block',
        tabAction: 'nuke',
        profileHref: href,
        targetUrl: href,
        requestedUrl: href,
        url: href,
        noForegroundFallback: true
    })

    const firstPromise = sw.createOwnedTabInQueuedWorkerActionSurface(
        makeAction('https://www.quora.com/profile/Synthetic-Worker-Lock-First'),
        {url: 'https://www.quora.com/profile/Synthetic-Worker-Lock-First'}
    )
    const secondPromise = sw.createOwnedTabInQueuedWorkerActionSurface(
        makeAction('https://www.quora.com/profile/Synthetic-Worker-Lock-Second'),
        {url: 'https://www.quora.com/profile/Synthetic-Worker-Lock-Second'}
    )

    const first = await firstPromise
    assert.ok(first?.id)

    // The second call now waits (see WORKER_ACTION_SURFACE_SLOT_WAIT_TIMEOUT_MS)
    // instead of rejecting immediately -- since nothing closes the first
    // tab in this test, the wait runs out and it still rejects the same
    // way, just after the fake clock is ticked past that timeout.
    let secondError = null
    const second = await settleWithFakeTimersInSmallSteps(secondPromise.catch(error => {
        secondError = error
        return null
    }), timers, {stepMs: 200, maxSteps: 60})

    assert.equal(second, null)
    assert.ok(secondError)
    assert.match(secondError.message, /worker-action-surface-busy/)
})

test('createOwnedTabInQueuedWorkerActionSurface proceeds as soon as the occupying tab closes, instead of rejecting immediately', async () => {
    // Companion to the "serializes two overlapping opens" test above: once
    // the first call actually finishes, the slot is occupied but not by a
    // *racing* caller anymore -- a busy second attempt should wait for the
    // real occupant to leave and then proceed, not reject on the spot the
    // way it used to. See WORKER_ACTION_SURFACE_SLOT_WAIT_TIMEOUT_MS's own
    // comment in shared/js/timeouts.js for the live cost this replaces.
    const {sw, browser, timers} = loadServiceWorkerHarness({now: 4000})
    const makeAction = href => ({
        ownerTabId: 'service-worker-queue-owner',
        actionKind: 'mute-block',
        tabAction: 'nuke',
        profileHref: href,
        targetUrl: href,
        requestedUrl: href,
        url: href,
        noForegroundFallback: true
    })

    const first = await sw.createOwnedTabInQueuedWorkerActionSurface(
        makeAction('https://www.quora.com/profile/Synthetic-Worker-Wait-First'),
        {url: 'https://www.quora.com/profile/Synthetic-Worker-Wait-First'}
    )
    assert.ok(first?.id)

    const secondPromise = sw.createOwnedTabInQueuedWorkerActionSurface(
        makeAction('https://www.quora.com/profile/Synthetic-Worker-Wait-Second'),
        {url: 'https://www.quora.com/profile/Synthetic-Worker-Wait-Second'}
    )
    await flushAsync(10)

    // Close the occupant the way a finished action does -- this should
    // wake the waiting second call via the onRemoved-driven signal rather
    // than it needing to wait out the full timeout.
    await browser.tabs.remove(first.id)

    const second = await settleWithFakeTimersInSmallSteps(secondPromise, timers)
    assert.ok(second?.id)
    assert.notEqual(second.id, first.id)
})

test('a profile tab left in the worker window after its profile finished is closed, so the next open can use the window', async () => {
    // 20 Oct: a blocked profile tab finished, was released from the runtime, and stayed open in the worker window. The surface stayed
    // busy for every later open. An orphaned profile tab is closed once it has looked orphaned for the grace period.
    const {sw, browser, timers} = loadServiceWorkerHarness({now: 4000})
    const makeAction = href => ({
        ownerTabId: 'service-worker-queue-owner',
        actionKind: 'mute-block',
        tabAction: 'nuke',
        profileHref: href,
        targetUrl: href,
        requestedUrl: href,
        url: href,
        noForegroundFallback: true
    })
    const orphanHref = 'https://www.quora.com/profile/Synthetic-Worker-Orphan-First'
    const orphan = await sw.createOwnedTabInQueuedWorkerActionSurface(makeAction(orphanHref), {url: orphanHref})
    assert.ok(orphan?.id)
    // The first look only starts the grace period, so an open right away still waits and gives up.
    await settleWithFakeTimersInSmallSteps(
        sw.createOwnedTabInQueuedWorkerActionSurface(makeAction('https://www.quora.com/profile/Synthetic-Worker-Orphan-Early'), {url: 'https://www.quora.com/profile/Synthetic-Worker-Orphan-Early'}),
        timers
    ).catch(() => null)
    assert.equal(browser.__tabs.has(orphan.id), true, 'the orphan is not taken on its first look')
    // Past the grace period, the next open closes the orphan and takes the window.
    await timers.tick(11000)
    const next = await settleWithFakeTimersInSmallSteps(
        sw.createOwnedTabInQueuedWorkerActionSurface(makeAction('https://www.quora.com/profile/Synthetic-Worker-Orphan-Next'), {url: 'https://www.quora.com/profile/Synthetic-Worker-Orphan-Next'}),
        timers
    )
    assert.ok(next?.id)
    assert.equal(browser.__tabs.has(orphan.id), false, 'the orphaned profile tab was closed')
    assert.ok(sw.getFlightRecorderSnapshot({kind: 'orphaned-surface-tab-closed', limit: 5}).entries.length >= 1, 'the close is recorded')
})

test('createOwnedTabInQueuedWorkerActionSurface keeps waiting past an unrelated tab removal instead of failing on the first spurious wakeup', async () => {
    // notifyQueuedWorkerActionSurfaceSlotMaybeFreed (sw.js) fires on *any*
    // tab removal, not just the worker-window occupant's -- there's no
    // cheap way to tell from a bare removed tabId alone. The busy-wait
    // used to recheck once per wakeup and give up immediately if still
    // busy, so an unrelated tab closing elsewhere could fail a waiting
    // open faster than even a short timeout. Confirmed as a real
    // confound in this session's live A/B of the timeout value, not just
    // a tuning problem. This proves the fix: an unrelated removal wakes
    // the wait, finds the real occupant still there, and keeps waiting
    // for the next signal instead of giving up.
    const {sw, browser, timers} = loadServiceWorkerHarness({now: 4000})
    const makeAction = href => ({
        ownerTabId: 'service-worker-queue-owner',
        actionKind: 'mute-block',
        tabAction: 'nuke',
        profileHref: href,
        targetUrl: href,
        requestedUrl: href,
        url: href,
        noForegroundFallback: true
    })

    const first = await sw.createOwnedTabInQueuedWorkerActionSurface(
        makeAction('https://www.quora.com/profile/Synthetic-Worker-Spurious-First'),
        {url: 'https://www.quora.com/profile/Synthetic-Worker-Spurious-First'}
    )
    assert.ok(first?.id)

    const secondPromise = sw.createOwnedTabInQueuedWorkerActionSurface(
        makeAction('https://www.quora.com/profile/Synthetic-Worker-Spurious-Second'),
        {url: 'https://www.quora.com/profile/Synthetic-Worker-Spurious-Second'}
    )
    await flushAsync(10)

    // An unrelated tab, elsewhere in the browser, closes first -- this
    // should wake the wait but NOT resolve it, since the real occupant
    // (first.id) is still there.
    const unrelatedTab = await browser.tabs.create({url: 'https://www.quora.com/notifications', active: false})
    await browser.tabs.remove(unrelatedTab.id)
    await flushAsync(10)

    let settledEarly = false
    secondPromise.then(() => { settledEarly = true }, () => { settledEarly = true })
    await flushAsync(10)
    assert.equal(settledEarly, false, 'the wait resolved on an unrelated tab removal instead of continuing to wait')

    // Now close the real occupant -- this should be the signal that
    // actually unblocks the second call.
    await browser.tabs.remove(first.id)
    const second = await settleWithFakeTimersInSmallSteps(secondPromise, timers)
    assert.ok(second?.id)
    assert.notEqual(second.id, first.id)
})

test('service-worker reuses existing worker window after in-memory surface state is lost', async () => {
    const href = 'https://www.quora.com/profile/Synthetic-Worker-Surface-Reuse'
    const runId = 'run-worker-surface-reuse'
    const attemptId = 'attempt-worker-surface-reuse'
    const browser = createFakeBrowser({
        mbCoordinatorPaused: false,
        mbCoordinatorQueue: {
            [href]: {
                runId,
                status: 'queued',
                actionKind: 'mute-block',
                executorTabAction: 'nuke',
                executorOwner: 'service-worker',
                serviceWorkerOwned: true,
                executorNoForegroundFallback: true,
                executorMaxConcurrent: 1,
                targetProfileHref: href,
                requestedUrl: href,
                dedupeKey: href,
                coordinatorKey: href,
                queuedAt: 2000,
                updatedAt: 2000,
                attemptId,
                attemptNumber: 1,
                milestones: {}
            }
        },
        mbCoordinatorRuns: {
            [runId]: {
                id: runId,
                sourceType: 'profile-search',
                status: 'active',
                targetProfileHrefs: [href],
                targetWorkKeys: [href]
            }
        },
        mbCoordinatorEvents: [],
            [LEGACY_PROFILE_PROGRESS_KEY]: {}
    })
    const existingSurface = await browser.windows.create({
        url: browser.runtime.getURL('coordinator.html#progress'),
        focused: false,
        type: 'normal'
    })
    const duplicateSurface = await browser.windows.create({
        url: browser.runtime.getURL('coordinator.html#progress'),
        focused: false,
        type: 'normal'
    })
    const {sw, storage, timers} = loadServiceWorkerHarness({browser, now: 2085})
    const userTab = await browser.tabs.create({url: 'https://www.quora.com/search?q=elon', active: true})
    const windowCountBefore = browser.__windows.size

    await settleWithFakeTimers(sw.resumeCoordinatorQueueExecution({
        tabId: 'service-worker-queue-owner',
        windowId: null
    }, {
        serviceWorkerOwned: true,        skipAuthorityReconcile: true,
        awaitFill: true
    }), timers, [0, 0, 0, 500, 0, 0, 1000, 0, 0, 5000, 0, 0])
    await waitFor(
        () => !browser.__windows.has(duplicateSurface.id),
        'duplicate worker action surface was not closed',
        {timers, attempts: 20, tickMs: 100}
    )

    let profileTab = listTabs(browser).find(tab =>
        tab.url === href &&
        [existingSurface.id, duplicateSurface.id].includes(tab.windowId) &&
        browser.__windows.has(tab.windowId))
    if(!profileTab) {
        await settleWithFakeTimers(sw.resumeCoordinatorQueueExecution({
            tabId: 'service-worker-queue-owner',
            windowId: null
        }, {
            serviceWorkerOwned: true,            skipAuthorityReconcile: true,
            awaitFill: true
        }), timers, [0, 0, 0, 500, 0, 0, 1000, 0, 0, 5000, 0, 0])
        profileTab = listTabs(browser).find(tab =>
            tab.url === href &&
            [existingSurface.id, duplicateSurface.id].includes(tab.windowId) &&
            browser.__windows.has(tab.windowId))
    }
    if(!profileTab) {
        assert.ok((sw.state().queueWakeupCounters.storageUpdate?.timedOut || 0) || (sw.state().queueWakeupCounters['storageUpdate.timedOut'] || 0))
        return
    }
    assert.ok(browser.__windows.size <= windowCountBefore)
    assert.ok([existingSurface.id, duplicateSurface.id].includes(profileTab?.windowId))
    assert.equal((await browser.tabs.get(userTab.id)).active, true)
    const progressRecorded = await waitFor(
        () => getProgressShardRecord(storage, href)?.status === 'tab-opening',
        'reused worker action surface progress was not recorded',
        {timers, attempts: 60, tickMs: 100}
    ).catch(() => false)
    if(!progressRecorded) {
        assert.ok((sw.state().queueWakeupCounters.storageUpdate?.timedOut || 0) ||
            (sw.state().queueWakeupCounters['storageUpdate.timedOut'] || 0) ||
            (sw.state().queueWakeupCounters['storageUpdate.fallbackReturned'] || 0))
        return
    }
    assert.equal(storage[LEGACY_PROFILE_PROGRESS_KEY][href], undefined)
    assert.equal(getProgressShardRecord(storage, href).actionSurfaceMode, 'worker-window')
    assert.equal(sw.state().queueWakeupCounters['actionSurface.workerWindow.created'] || 0, 0)
    assert.ok(browser.__removedTabs.includes(duplicateSurface.tabs[0].id))
})

