test('service-worker worker window stays open while durable queued work remains', async () => {
    const firstHref = 'https://www.quora.com/profile/Synthetic-Worker-Surface-Batch-First'
    const secondHref = 'https://www.quora.com/profile/Synthetic-Worker-Surface-Batch-Second'
    const runId = 'run-worker-surface-batch'
    const firstAttemptId = 'attempt-worker-surface-batch-first'
    const secondAttemptId = 'attempt-worker-surface-batch-second'
    const {browser, sw, storage, timers} = loadServiceWorkerHarness({
        now: 2089,
        storage: {
            mbCoordinatorPaused: false,
            mbCoordinatorQueue: {
                [firstHref]: {
                    ...makeQueuedCoordinatorRow({href: firstHref, runId, attemptId: firstAttemptId, now: 2000}),
                    executorNoForegroundFallback: true,
                    executorMaxConcurrent: 1
                },
                [secondHref]: {
                    ...makeQueuedCoordinatorRow({href: secondHref, runId, attemptId: secondAttemptId, now: 2001}),
                    executorNoForegroundFallback: true,
                    executorMaxConcurrent: 1
                }
            },
            mbCoordinatorRuns: {
                [runId]: makeCoordinatorRun({href: firstHref, runId, targetProfileHrefs: [firstHref, secondHref]})
            },
            mbCoordinatorEvents: [],
            [LEGACY_PROFILE_PROGRESS_KEY]: {}
        }
    })
    await browser.tabs.create({url: 'https://www.quora.com/search?q=elon', active: true})

    await settleWithFakeTimers(sw.resumeCoordinatorQueueExecution({
        tabId: 'service-worker-queue-owner',
        windowId: null
    }, {
        serviceWorkerOwned: true,
        skipAuthorityReconcile: true,
        awaitFill: true
    }), timers)

    const profileTab = listTabs(browser).find(tab => tab.url === firstHref)
    assert.ok(profileTab?.id)
    const workerWindowId = profileTab.windowId
    assert.ok(browser.__windows.has(workerWindowId))
    await waitFor(
        () => sw.coordinatorAuthority.current().queue[firstHref]?.status === 'active',
        'first worker-window profile tab did not become durable active before close',
        {timers, attempts: 20, tickMs: 100}
    )

    await settleWithFakeTimers(browser.runtime.sendMessage({
        action: 'record-job-terminal',
        profileHref: firstHref,
        patch: {
            status: 'blocked',
            blockSucceeded: true,
            blockedAt: 2100,
            terminalAt: 2100,
            actionKind: 'mute-block',
            runId,
            attemptId: firstAttemptId,
            attemptNumber: 1
        },
        attemptId: firstAttemptId,
        attemptNumber: 1
    }, {
        tab: {id: profileTab.id, url: firstHref, windowId: workerWindowId}
    }), timers)

    await settleWithFakeTimers(browser.runtime.sendMessage({
        action: 'close-tab',
        attemptId: firstAttemptId,
        attemptNumber: 1
    }, {
        tab: {id: profileTab.id, url: firstHref, windowId: workerWindowId}
    }), timers)
    await timers.tick(2000)
    await flushAsync(20)

    const recoveredQueue = getRecoveredCoordinatorQueue(storage)
    // The shortened terminal-progress settlement defer (see
    // TERMINAL_PROGRESS_SETTLEMENT_DEFER_MS) means queue continuation can
    // pick the second row up for execution within this same tick budget, so
    // it may already have advanced from 'queued' to 'active' by the time
    // this reads storage. Either way it's still durable, non-terminal work
    // -- which is what this test is actually checking keeps the worker
    // window open below.
    assert.ok(['queued', 'active'].includes(recoveredQueue[secondHref].status))
    assert.equal(browser.__tabs.has(profileTab.id), false)
    assert.equal(browser.__windows.has(workerWindowId), true)
    assert.equal(sw.state().queueWakeupCounters['actionSurface.workerWindow.cleanupBusy.durableQueued'] > 0, true)
})

test('worker action surface stays up for durable queued backlog that has not been dispatched to it yet', async () => {
    // Live incident (2026-09-17): hasDurableQueuedBacklogForActionSurface
    // only recognized a queued item as belonging to this surface once it
    // already carried an actionSurfaceWindowId/actionSurfaceMode tag --
    // which is only set at dispatch time (tagActionWithQueuedWorkerSurface).
    // A freshly-queued item sitting in the backlog (the normal case for
    // most of a batch) carries neither tag yet, so in the gap between one
    // queued tab releasing and the next being claimed, this check saw no
    // recognized backlog, the window closed, and had to be recreated
    // moments later for the very next item. Confirmed live via
    // actionSurface.workerWindow.created/closed.idle-after-release
    // counters both incrementing within the same short batch.
    const href = 'https://www.quora.com/profile/Synthetic-Worker-Surface-Undispatched-Backlog'
    const {sw, browser} = loadServiceWorkerHarness({
        now: 5000,
        storage: {
            mbCoordinatorPaused: false,
            mbCoordinatorQueue: {
                [href]: {
                    status: 'queued',
                    actionKind: 'mute-block',
                    targetProfileHref: href,
                    requestedUrl: href,
                    coordinatorKey: href,
                    queuedAt: 5000,
                    updatedAt: 5000,
                    milestones: {}
                }
            },
            mbCoordinatorRuns: {},
            mbCoordinatorEvents: []
        }
    })

    const workerWindowId = 555
    browser.__windows.set(workerWindowId, {id: workerWindowId, focused: false, type: 'normal'})

    const closed = await sw.closeQueuedWorkerActionSurfaceIfIdle('idle-after-release', {
        windowId: workerWindowId
    })

    assert.equal(closed, false)
    assert.equal(browser.__windows.has(workerWindowId), true)
    assert.equal(sw.state().queueWakeupCounters['actionSurface.workerWindow.cleanupBusy.durableQueued'] > 0, true)
})

test('worker action surface with tracked runtime work is not torn down just because its tab has not shown a profile url yet', async () => {
    // Regression for a live 2026-09-16 incident under the
    // 'idle-after-active-missing-tab-prepass-requeue' cleanup reason: the
    // busy-detection counter (52) came in lower than the actual-close
    // counter (58) in the very same run -- the guard was real but had a
    // gap. closeQueuedWorkerActionSurfaceIfIdle used to require *both*
    // hasQueuedWorkerActionSurfaceRuntimeWork (real, tracked queued-tab/
    // pending-action bookkeeping) *and* a tab whose current *url* already
    // matched the Quora profile pattern before it treated the worker
    // window as busy. Right after an active-missing-tab requeue gets
    // refilled, the freshly (re)opened tab can sit on about:blank for a
    // beat while it navigates -- isIdleQueuedWorkerActionSurfaceTab treats
    // about:blank as idle too -- so a window with genuinely tracked,
    // pending work closed out from under it. This proves
    // hasQueuedWorkerActionSurfaceRuntimeWork alone is now sufficient to
    // block the close, without needing the url to have caught up yet.
    const {sw, browser} = loadServiceWorkerHarness({
        now: 5000,
        storage: {
            mbCoordinatorPaused: false,
            mbCoordinatorQueue: {},
            mbCoordinatorRuns: {},
            mbCoordinatorEvents: []
        }
    })

    const workerWindowId = 777
    const workerTabId = 888
    browser.__windows.set(workerWindowId, {id: workerWindowId, focused: false, type: 'normal'})
    browser.__tabs.set(workerTabId, {id: workerTabId, windowId: workerWindowId, url: 'about:blank', active: true})

    sw.__testAddProvisionalQueuedTab(workerTabId, {
        actionSurfaceMode: 'worker-window',
        actionSurfaceWindowId: workerWindowId,
        profileHref: 'https://www.quora.com/profile/Synthetic-Worker-Surface-Racing-Navigation',
        coordinatorKey: 'https://www.quora.com/profile/Synthetic-Worker-Surface-Racing-Navigation',
        attemptId: 'attempt-worker-surface-racing-navigation',
        attemptNumber: 1
    })

    const closed = await sw.closeQueuedWorkerActionSurfaceIfIdle('idle-after-active-missing-tab-prepass-requeue', {
        windowId: workerWindowId
    })

    assert.equal(closed, false)
    assert.equal(browser.__windows.has(workerWindowId), true)
    assert.equal(sw.state().queueWakeupCounters['actionSurface.workerWindow.cleanupBusy'] > 0, true)
    assert.equal(!!sw.state().queueWakeupCounters['actionSurface.workerWindow.closed.idle-after-active-missing-tab-prepass-requeue'], false)
})

test('confirmation promotion in no-foreground worker window briefly focuses and restores caller window', async () => {
    const href = 'https://www.quora.com/profile/Synthetic-Worker-Surface-Promote'
    const runId = 'run-worker-surface-promote'
    const attemptId = 'attempt-worker-surface-promote'
    const {browser, sw, storage, timers} = loadServiceWorkerHarness({
        now: 2090,
        storage: {
            mbCoordinatorPaused: false,
            mbCoordinatorQueue: {
                [href]: {
                    runId,
                    status: 'queued',
                    actionKind: 'mute-block',
                    executorTabAction: 'nuke',
                    executorOwner: 'service-worker',
                    serviceWorkerOwned: true,
                    executorNoForegroundFallback: true,
                    executorMaxConcurrent: 1,
                    targetProfileHref: href,
                    requestedUrl: href,
                    dedupeKey: href,
                    coordinatorKey: href,
                    queuedAt: 2000,
                    updatedAt: 2000,
                    attemptId,
                    attemptNumber: 1,
                    milestones: {}
                }
            },
            mbCoordinatorRuns: {
                [runId]: {
                    id: runId,
                    sourceType: 'profile-search',
                    status: 'active',
                    targetProfileHrefs: [href],
                    targetWorkKeys: [href]
                }
            },
            mbCoordinatorEvents: [],
            [LEGACY_PROFILE_PROGRESS_KEY]: {}
        }
    })
    const userTab = await browser.tabs.create({url: 'https://www.quora.com/search?q=elon', active: true})

    await settleWithFakeTimers(sw.resumeCoordinatorQueueExecution({
        tabId: 'service-worker-queue-owner',
        windowId: null
    }, {
        serviceWorkerOwned: true,        skipAuthorityReconcile: true,
        awaitFill: true
    }), timers)

    const profileTab = await waitFor(
        () => listTabs(browser).find(tab => tab.url === href),
        'worker-window profile tab did not open before promotion',
        {timers, attempts: 20, tickMs: 100}
    )
    const workerWindowId = profileTab.windowId
    await waitFor(
        () => sw.coordinatorAuthority.current().queue[href]?.status === 'active',
        'worker-window profile tab did not become durable active before promotion',
        {timers, attempts: 20, tickMs: 100}
    )
    const claimed = await browser.runtime.sendMessage({action: 'claim-tab-action'}, {tab: profileTab})

    assert.equal(claimed.noForegroundFallback, true)
    assert.equal(claimed.actionSurfaceMode, 'worker-window')
    browser.__windowUpdates.splice(0, browser.__windowUpdates.length)

    const result = await browser.runtime.sendMessage({
        action: 'begin-profile-action',
        profileHref: href,
        actionKind: 'mute-block',
        reason: 'block-confirmation',
        attemptId,
        attemptNumber: 1
    }, {tab: profileTab})

    const metadata = sw.state().queuedTabMetadata.find(([tabId]) => tabId === profileTab.id)?.[1] || {}
    assert.equal(result.begun, true, JSON.stringify(result))
    assert.equal(result.foregroundPromoted, true)
    assert.equal(result.foregroundMode, 'worker-window')
    assert.equal(metadata.foregroundMode, 'worker-window')
    assert.equal(metadata.foregroundPromotionReason, 'block-confirmation')
    assert.equal(metadata.foregroundRestoreTabId, userTab.id)
    assert.equal(metadata.foregroundRestoreWindowId, userTab.windowId)
    assert.equal(browser.__windowUpdates.some(update =>
        update.windowId === workerWindowId && update.options?.focused === true
    ), true)
    assert.equal(result.actionLease.tabId, profileTab.id)
    const actionLeaseRow = sw.coordinatorAuthority.current().queue[href]
    if(actionLeaseRow.actionLease) {
        assert.equal(actionLeaseRow.actionLease.tabId, profileTab.id)
    }
    else {
        assert.equal(actionLeaseRow.actionLeaseReleaseReason, 'active-transition-fast-detached-fast-executor-preflight')
    }

    browser.__windowUpdates.splice(0, browser.__windowUpdates.length)
    const released = await browser.runtime.sendMessage({
        action: 'release-action-lease',
        profileHref: href,
        actionKind: 'mute-block',
        reason: 'confirmation-finished',
        attemptId,
        attemptNumber: 1
    }, {tab: profileTab})

    assert.equal(released.released, true)
    assert.equal((await browser.tabs.get(userTab.id)).active, true)
    assert.equal(browser.__windows.get(userTab.windowId).focused, true)
    assert.equal(browser.__windowUpdates.some(update =>
        update.windowId === userTab.windowId && update.options?.focused === true
    ), true)
})

test('begin-profile-action promotes from sender tab when tab lookup is transiently missing', async () => {
    const href = 'https://www.quora.com/profile/Synthetic-Sender-Tab-Promote'
    const runId = 'run-sender-tab-promote'
    const attemptId = 'attempt-sender-tab-promote'
    const tabId = 252
    const {browser, sw, storage} = loadServiceWorkerHarness({
        now: 3060,
        storage: {
            mbCoordinatorPaused: false,
            mbCoordinatorQueue: {
                [href]: {
                    runId,
                    status: 'active',
                    actionKind: 'mute-block',
                    executorTabAction: 'nuke',
                    executorOwner: 'service-worker',
                    serviceWorkerOwned: true,
                    executorNoForegroundFallback: true,
                    targetProfileHref: href,
                    requestedUrl: href,
                    dedupeKey: href,
                    coordinatorKey: href,
                    queuedAt: 2960,
                    activeAt: 3060,
                    updatedAt: 3060,
                    tabId,
                    attemptId,
                    attemptNumber: 1,
                    milestones: {}
                }
            },
            mbCoordinatorRuns: {},
            mbCoordinatorEvents: [],
            [LEGACY_PROFILE_PROGRESS_KEY]: {}
        }
    })
    browser.__setNextTabId(tabId)
    const tab = await browser.tabs.create({url: href, active: false})
    sw.__testAddProvisionalQueuedTab(tab.id, {
        profileHref: href,
        coordinatorKey: href,
        requestedUrl: href,
        ownerTabId: 'service-worker-queue-owner',
        runId,
        tabAction: 'nuke',
        actionKind: 'mute-block',
        noForegroundFallback: true,
        actionSurfaceMode: 'worker-window',
        attemptId,
        attemptNumber: 1
    })
    const originalGet = browser.tabs.get.bind(browser.tabs)
    browser.tabs.get = async candidateTabId => {
        if(Number.parseInt(candidateTabId, 10) === tabId) {
            throw new Error(`no fake tab ${candidateTabId}`)
        }
        return originalGet(candidateTabId)
    }

    const result = await browser.runtime.sendMessage({
        action: 'begin-profile-action',
        profileHref: href,
        actionKind: 'mute-block',
        reason: 'block-confirmation',
        attemptId,
        attemptNumber: 1
    }, {tab})
    browser.tabs.get = originalGet

    assert.equal(result.begun, true)
    assert.equal(result.granted, true)
    assert.equal(result.foregroundPromoted, true)
    assert.equal(result.foregroundMode, 'worker-window')
    const recoveredQueue = recoverProjectedState(getStoredCoordinatorQueueWal(storage)).projected.state.queue
    if(recoveredQueue[href].actionLease) {
        assert.equal(recoveredQueue[href].actionLease.tabId, tab.id)
    }
    assert.ok(['', 'queued-tab-slot-release'].includes(recoveredQueue[href].actionLeaseReleaseReason || ''))
})

