// 2026-09-15: a big Space-feed submission that mostly deduped against
// already-known rows used to leave no durable trace of the breakdown --
// {queued, merged} came back in the message response, but nothing persisted
// it, so a dashboard reopened later (or a user who wasn't watching the
// button) had no way to tell "700 requested, only 50 were actually new" from
// "the other 650 got lost". This proves mbCoordinatorLastEnqueueSummary
// captures the requested/queued/merged breakdown for the dashboard to read.
test('enqueue durably records a requested/queued/merged summary for the dashboard', async () => {
    const runId = 'run-last-enqueue-summary'
    const alreadyKnownHref = 'https://www.quora.com/profile/Synthetic-Last-Enqueue-Known'
    const newHrefA = 'https://www.quora.com/profile/Synthetic-Last-Enqueue-New-A'
    const newHrefB = 'https://www.quora.com/profile/Synthetic-Last-Enqueue-New-B'
    const sourceSender = {tab: {id: 12, windowId: 1}}
    const {browser, storage, sw} = loadServiceWorkerHarness({
        now: 200000,
        storage: {
            mbCoordinatorQueue: {
                [alreadyKnownHref]: makeActiveCoordinatorRow({
                    href: alreadyKnownHref,
                    runId: 'run-earlier',
                    attemptId: 'attempt-earlier',
                    tabId: null,
                    now: 190000
                })
            }
        }
    })

    await browser.runtime.sendMessage({
        action: 'enqueue-coordinator-items',
        run: {id: runId, sourceType: 'space-feed'},
        source: {type: 'space-feed', pageUrl: 'https://www.quora.com/space/example'},
        items: [alreadyKnownHref, newHrefA, newHrefB].map(href => ({
            runId,
            targetProfileHref: href,
            requestedUrl: href,
            dedupeKey: href
        }))
    }, sourceSender)
    await Promise.resolve()
    await Promise.resolve()
    await Promise.resolve()

    const summary = storage.mbCoordinatorLastEnqueueSummary
    assert.equal(summary?.requested, 3)
    assert.equal(summary?.queued, 2)
    assert.equal(summary?.merged, 1)
    assert.equal(summary?.sourceType, 'space-feed')
    assert.equal(sw.state().queueWakeupCounters['job.enqueued'] || 0, 3)
})

test('queued profile actions are throttled and opened background', async () => {
    const firstHref = 'https://www.quora.com/profile/Synthetic-Legacy-Foreground-1'
    const secondHref = 'https://www.quora.com/profile/Synthetic-Legacy-Foreground-2'
    const runId = 'run-legacy-foreground-throttle'
    const sourceSender = {tab: {id: 12, windowId: 1}}
    const {browser, sw, storage, timers} = loadServiceWorkerHarness({now: 2500})

    await browser.runtime.sendMessage({
        action: 'enqueue-coordinator-items',
        run: {
            id: runId,
            sourceType: 'profile-search'
        },
        source: {
            type: 'profile-search',
            pageUrl: 'https://www.quora.com/search?q=synthetic&type=profile'
        },
        execute: {
            tabAction: 'nuke',
            maxConcurrent: 3,
            noForegroundFallback: true
        },
        items: [firstHref, secondHref].map(href => ({
            runId,
            targetProfileHref: href,
            requestedUrl: href,
            dedupeKey: href
        }))
    }, sourceSender)

    const opened = await waitFor(
        () => {
            const tabs = listTabs(browser).filter(tab => [firstHref, secondHref].includes(tab.url))
            return tabs.length ? tabs : null
        },
        'queued profile throttle did not open an executor tab',
        {timers}
    )

    assert.equal(opened.length, 1)
    // 2026-09-29/2026-10-08: this used to also require the window stay
    // unfocused whenever the tab ended up active, then briefly required
    // the opposite (the worker window's one active tab was always
    // foregrounded, per a since-reversed explicit user request -- see
    // createOwnedTabInQueuedWorkerActionSurface's own comment, sw.js).
    // window focus is no longer coupled to a tab's own active-within-its-
    // window state either way, so this just confirms a tab opened; the
    // throttling this test is actually about (only one of the two hrefs
    // opens a tab) is unaffected.
    if(opened[0].active !== true) {
        assert.equal(opened[0].active, false)
    }
    await waitFor(
        () => sw.coordinatorAuthority.current().queue[opened[0].url]?.status === 'active',
        'legacy foreground executor tab did not persist active authority state',
        {timers}
    )

    const queuedHref = opened[0].url === firstHref ? secondHref : firstHref
    assert.ok(['queued', 'active'].includes(getRecoveredCoordinatorQueue(storage)[queuedHref].status))
})

