test('queue-only fast executor uses resident authority without legacy progress load', async () => {
    const href = 'https://www.quora.com/profile/Synthetic-Resident-Fast-Resume'
    const runId = 'run-resident-fast-resume'
    const attemptId = 'attempt-resident-fast-resume'
    const {browser, sw, storage, timers} = loadServiceWorkerHarness({
        now: 3630,
        storage: {
            mbCoordinatorPaused: false,
            mbCoordinatorQueue: {
                [href]: makeQueuedCoordinatorRow({href, runId, attemptId, now: 3630})
            },
            mbCoordinatorRuns: {
                [runId]: makeCoordinatorRun({href, runId})
            },
            mbCoordinatorEvents: [],
            [LEGACY_PROFILE_PROGRESS_KEY]: {
                [href]: {
                    profileHref: href,
                    status: 'queued',
                    attemptId: 'stale-progress-attempt',
                    attemptNumber: 1
                }
            }
        }
    })
    await sw.coordinatorAuthority.hydrate()
    const originalGet = browser.storage.local.get.bind(browser.storage.local)
    const forbiddenReads = []
    browser.storage.local.get = async defaults => {
        const stack = new Error().stack
        const finalOpenAuthorityValidation = stack.includes('validateQueuedTabOpenAgainstCurrentAuthority')
        if(defaults &&
            Object.prototype.hasOwnProperty.call(defaults, LEGACY_PROFILE_PROGRESS_KEY)) {
            forbiddenReads.push({keys: Object.keys(defaults).sort(), stack})
            throw new Error('synthetic queue-only resume legacy progress read')
        }
        if(defaults &&
            Object.prototype.hasOwnProperty.call(defaults, 'mbCoordinatorQueue') &&
            Object.prototype.hasOwnProperty.call(defaults, 'mbCoordinatorRuns') &&
            !finalOpenAuthorityValidation &&
            Object.prototype.hasOwnProperty.call(defaults, 'mbCoordinatorQueueWal.meta')) {
            forbiddenReads.push({keys: Object.keys(defaults).sort(), stack})
            throw new Error('synthetic queue-only resume full authority read')
        }
        return originalGet(defaults)
    }

    const originalCreate = browser.tabs.create.bind(browser.tabs)
    const result = await settleWithFakeTimers(
        sw.runCoordinatorQueueExecutorFastPath('synthetic-resident-fast-resume', {
            awaitFill: true,
            returnAfterDurableActive: true
        }),
        timers,
        [0, 500, 1000, 5000]
    )
    browser.storage.local.get = originalGet
    browser.tabs.create = originalCreate

    assert.deepEqual(forbiddenReads, [])
    assert.equal(result.fastPath, true)
    assert.equal(result.changed, true)
    assert.equal(result.queued, 1)
    assert.equal(listTabs(browser).some(tab => tab.url === href), true)
    assert.equal(sw.coordinatorAuthority.current().queue[href].status, 'active')
    assert.equal(storage.mbCoordinatorQueue[href].status, 'queued')
})

test('awaited queue fill releases promise and preserves retry action when tab creation hangs', async () => {
    const href = 'https://www.quora.com/profile/Synthetic-Hung-Tab-Create'
    const runId = 'run-hung-tab-create'
    const attemptId = 'attempt-hung-tab-create'
    const {browser, sw, storage, timers} = loadServiceWorkerHarness({
        now: 3642,
        storage: {
            mbCoordinatorPaused: false,
            mbCoordinatorQueue: {
                [href]: makeQueuedCoordinatorRow({href, runId, attemptId, now: 3642})
            },
            mbCoordinatorRuns: {
                [runId]: makeCoordinatorRun({href, runId})
            },
            mbCoordinatorEvents: [],
            [LEGACY_PROFILE_PROGRESS_KEY]: {}
        }
    })
    await sw.coordinatorAuthority.hydrate()
    const originalCreate = browser.tabs.create.bind(browser.tabs)
    browser.tabs.create = async () => new Promise(() => {})

    const result = await settleWithFakeTimers(
        sw.runCoordinatorQueueExecutorFastPath('synthetic-hung-tab-create', {
            awaitFill: true,
            skipAuthorityReconcile: true,
            forceDurableQueueReload: false
        }),
        timers,
        [
            0,
            500,
            1000,
            sw.state().constants.QUEUED_TAB_CREATE_TIMEOUT_MS,
            1000,
            sw.state().constants.QUEUED_TAB_CREATE_TIMEOUT_MS,
            1000,
            sw.state().constants.QUEUED_TAB_CREATE_TIMEOUT_MS * 2,
            1000
        ]
    )
    browser.tabs.create = originalCreate

    assert.equal(result.fastPath, true)
    assert.equal(result.changed, true)
    assert.equal(result.queued, 1)
    assert.ok((sw.state().queueWakeupCounters['pump.noop.tabCreateTimedOut'] || 0) >= 1)
    assert.equal(listTabs(browser).some(tab => tab.url === href), false)
    assert.equal(sw.coordinatorAuthority.current().queue[href].status, 'queued')
    assert.equal(storage.mbCoordinatorQueue[href].status, 'queued')
    assert.equal(sw.state().hasCoordinatorQueueResumeTimeout, true)
    // The work stays durable. The timeout puts the action back, and the retry can run while the create still hangs, so
    // the runtime queue need not show it at this point. Once the scheduled resume has run, the authority row is still
    // the same work: queued, or picked up by a new open. It is never dropped or terminalized.
    for (let index = 0; index < 4; index += 1) {
        await timers.tick(1000)
        await flushAsync(20)
    }
    assert.ok(['queued', 'active'].includes(sw.coordinatorAuthority.current().queue[href]?.status))
})

test('final open authority timeout preserves queued action for retry', async () => {
    const href = 'https://www.quora.com/profile/Synthetic-Final-Open-Timeout-Retry'
    const runId = 'run-final-open-timeout-retry'
    const attemptId = 'attempt-final-open-timeout-retry'
    const {browser, sw, storage, timers} = loadServiceWorkerHarness({
        now: 3644,
        storage: {
            mbCoordinatorPaused: false,
            mbCoordinatorQueue: {
                [href]: makeQueuedCoordinatorRow({href, runId, attemptId, now: 3644})
            },
            mbCoordinatorRuns: {
                [runId]: makeCoordinatorRun({href, runId})
            },
            mbCoordinatorEvents: [],
            [LEGACY_PROFILE_PROGRESS_KEY]: {}
        }
    })
    await sw.coordinatorAuthority.hydrate()

    const originalCurrent = sw.coordinatorAuthority.current
    sw.coordinatorAuthority.current = () => {
        const stack = new Error().stack || ''
        if(stack.includes('validateQueuedTabOpenAgainstCurrentAuthority')) return null
        return originalCurrent()
    }
    const originalGet = browser.storage.local.get.bind(browser.storage.local)
    browser.storage.local.get = defaults => {
        const stack = new Error().stack || ''
        if(stack.includes('validateQueuedTabOpenAgainstCurrentAuthority')) {
            throw new Error('synthetic final open authority unavailable')
        }
        return originalGet(defaults)
    }

    const result = await settleWithFakeTimers(
        sw.runCoordinatorQueueExecutorFastPath('synthetic-final-open-timeout-retry', {
            awaitFill: true,
            skipAuthorityReconcile: true,
            forceDurableQueueReload: false
        }),
        timers,
        [
            0,
            500,
            1000,
            5000
        ]
    )
    sw.coordinatorAuthority.current = originalCurrent
    browser.storage.local.get = originalGet

    assert.equal(result.fastPath, true)
    assert.equal(
        sw.state().queuedTabActions.length === 0 ||
            sw.state().queuedTabActions.some(action => action.profileHref === href),
        true
    )
    const openedFromResidentAuthority = listTabs(browser).some(tab => tab.url === href)
    if(openedFromResidentAuthority) {
        assert.ok(['opening', 'active', 'acting', 'settling'].includes(
            sw.coordinatorAuthority.current().queue[href].status
        ))
    }
    else {
        assert.equal(sw.coordinatorAuthority.current().queue[href].status, 'queued')
        assert.equal(storage.mbCoordinatorQueue[href].status, 'queued')
        assert.ok((sw.state().queueWakeupCounters['pump.changed.requeuedFinalOpenAuthorityUnavailable'] || 0) >= 1)
        assert.ok(sw.state().hasCoordinatorQueueResumeTimeout)
        assert.ok(sw.state().hasCoordinatorReconcileTimeout)
    }
})

