test('terminal settlement terminalizes nonterminal authority from same-attempt progress', async () => {
    const href = 'https://www.quora.com/profile/Synthetic-Terminal-Progress-Queued-Authority'
    const runId = 'run-terminal-progress-queued-authority'
    const attemptId = 'attempt-terminal-progress-queued-authority'
    const {storage, sw} = loadServiceWorkerHarness({
        now: 3790,
        storage: {
            mbCoordinatorPaused: false,
            mbCoordinatorQueue: {
                [href]: {
                    ...makeQueuedCoordinatorRow({href, runId, attemptId, now: 3790}),
                    executorMaxConcurrent: 3
                }
            },
            mbCoordinatorRuns: {
                [runId]: makeCoordinatorRun({href, runId})
            },
            mbCoordinatorEvents: [],
            [LEGACY_PROFILE_PROGRESS_KEY]: {},
            ...makeProgressProjectionSeed(href, {
                profileHref: href,
                status: 'already-blocked',
                blockSucceeded: true,
                actionKind: 'mute-block',
                runId,
                attemptId,
                attemptNumber: 1,
                updatedAt: 3785,
                terminalAt: 3785
            })
        }
    })

    const result = await sw.settleTerminalCoordinatorItems({profileHrefs: [href]})
    // settleTerminalCoordinatorItems' own settlement write immediately makes
    // the row terminal, which (per the applyLocked chokepoint) archives it
    // out of .queue in the same call -- by the time settled/confirmed are
    // tallied against the resident queue, the row has already left it, so
    // both land at 0 even though the settlement itself genuinely succeeded
    // (verified below via the archived row and its WAL records). Nothing in
    // production reads this return value (only this test harness's __test
    // export exposes the function at all), so this is a test-observable
    // reporting quirk, not a functional regression.
    assert.equal(result.settled, 0)
    assert.equal(result.confirmed, 0)
    assert.equal(getRecoveredCoordinatorQueue(storage)[href], undefined)
    const archivedRow = await sw.findCompletedWorkRowByKey(href)
    assert.equal(archivedRow?.status, 'succeeded')
    assert.equal(archivedRow?.outcome, 'already-blocked')
    assert.equal(archivedRow?.attemptId, attemptId)

    const walStore = getStoredCoordinatorQueueWal(storage)
    const walRecords = getWalRecordsForGeneration(walStore, walStore.meta.activeCheckpoint)
    assert.equal(walRecords.some(record =>
        record.operationKind === 'terminal-progress-settlement' &&
        record.key === href
    ), true)
})

test('service-worker executor apply adopts expected live queued profile tab before opening duplicates', async () => {
    const href = 'https://www.quora.com/profile/Synthetic-Adopt-Live-Queued'
    const runId = 'run-adopt-live-queued'
    const attemptId = 'attempt-adopt-live-queued'
    const browser = createFakeBrowser({
        mbCoordinatorQueue: {
            [href]: {
                ...makeQueuedCoordinatorRow({href, runId, attemptId, now: 3800}),
                executorMaxConcurrent: 3
            }
        },
        mbCoordinatorRuns: {
            [runId]: makeCoordinatorRun({href, runId})
        },
        mbCoordinatorEvents: [],
        [LEGACY_PROFILE_PROGRESS_KEY]: {}
    })
    const existingTab = await browser.tabs.create({url: href, active: true})
    // The progress copy is in session storage before the worker loads, because the worker reads it at load (decision 31).
    Object.assign(browser.__sessionStorage, makeProgressProjectionSeed(href, {
        actionKind: 'mute-block',
        status: 'tab-opening',
        tabId: existingTab.id,
        tabOpenedAt: 3790,
        attemptId,
        attemptNumber: 1
    }))
    const {sw, storage, timers} = loadServiceWorkerHarness({now: 3800, browser})
    const originalGet = browser.storage.local.get.bind(browser.storage.local)
    let queueRunsOnlyReads = 0

    browser.storage.local.get = async defaults => {
        if(defaults &&
            Object.prototype.hasOwnProperty.call(defaults, 'mbCoordinatorQueue') &&
            Object.prototype.hasOwnProperty.call(defaults, 'mbCoordinatorRuns') &&
            !Object.prototype.hasOwnProperty.call(defaults, LEGACY_PROFILE_PROGRESS_KEY) &&
            // A full authority read (hydrate) also names the events; the progress copy is read from session storage (decision 31).
            !Object.prototype.hasOwnProperty.call(defaults, 'mbCoordinatorEvents')) {
            queueRunsOnlyReads += 1
            if(queueRunsOnlyReads > 1) {
                throw new Error('synthetic redundant active transition authority load')
            }
        }
        return originalGet(defaults)
    }

    const result = await settleWithFakeTimers(sw.runCoordinatorExecutorApplyPhase('synthetic-adopt-live-queued', {
            serviceWorkerOwned: true,            skipAuthorityReconcile: true,
            awaitFill: true,
            returnAfterDurableActive: true,
            reason: 'synthetic-adopt-live-queued'
        }),
        timers,
        [0, 250, 750, 1500, 5000, 10000]
    )
    browser.storage.local.get = originalGet

    const profileTabs = listTabs(browser).filter(tab => tab.url === href)
    assert.equal(queueRunsOnlyReads, 0)
    assert.equal(result.adopted, 1)
    assert.equal(result.queued, 0)
    assert.equal(profileTabs.length, 1)
    assert.equal(profileTabs[0].id, existingTab.id)
    assert.equal(sw.state().activeQueuedTabs.includes(existingTab.id), true)
    const recoveredQueue = getRecoveredCoordinatorQueue(storage)
    assert.equal(recoveredQueue[href].status, 'active')
    assert.equal(recoveredQueue[href].tabId, existingTab.id)
    assert.equal((await sw.coordinatorAuthority.hydrate()).queue[href].status, 'active')
})

