test('executor queue-only reconcile preserves fresh startup actor before no-actor failure', async () => {
    const href = 'https://www.quora.com/profile/Synthetic-Executor-Fresh-Startup-Actor'
    const runId = 'run-executor-fresh-startup-actor'
    const attemptId = 'attempt-executor-fresh-startup-actor'
    const {browser, sw, storage, timers} = loadServiceWorkerHarness({
        now: 3900,
        storage: {
            mbCoordinatorPaused: false,
            mbCoordinatorQueue: {
                [href]: makeActiveCoordinatorRow({href, runId, attemptId, tabId: null, now: 3900})
            },
            mbCoordinatorRuns: {
                [runId]: makeCoordinatorRun({href, runId})
            },
            mbCoordinatorEvents: [],
            [LEGACY_PROFILE_PROGRESS_KEY]: {}
        }
    })
    const tab = await browser.tabs.create({url: href, active: true})
    sw.__testAddProvisionalQueuedTab(tab.id, {
        profileHref: href,
        coordinatorKey: href,
        requestedUrl: href,
        ownerTabId: 'service-worker-queue-owner',
        tabAction: 'nuke',
        actionKind: 'mute-block',
        runId,
        attemptId,
        attemptNumber: 1,
        openedAt: 3890
    })

    // This item's single tabId gets probed for "close-if-blocked" twice in
    // one apply-phase pass -- once via sweepProfileTabsWithoutActiveQueueAuthority's
    // prepass, once via the main per-item loop's
    // terminalizeActiveCoordinatorItemFromBlockedLiveTab call -- and the
    // second probe hits CLOSE_IF_BLOCKED_MIN_PROBE_INTERVAL_MS's (750ms)
    // real (fake-timer-backed) throttle wait since Date.now() hasn't
    // advanced. Ticking the fake clock forward in small (50ms) increments,
    // stopping the instant the call settles, clears that wait without also
    // firing the 1000ms scheduleCoordinatorReconcile call the unresolved-case
    // branch makes afterward -- a single large tick (e.g. settleWithFakeTimers'
    // default steps) overshoots both at once, and the assertions below need
    // that reconcile timeout to still be pending. Without ticking the clock
    // at all, the wait never resolves and the test hangs forever with
    // nothing left to time it out (see
    // project_swsynthetic_silent_hang_2026_10_07 in project memory).
    const result = await settleWithFakeTimersInSmallSteps(sw.runCoordinatorExecutorApplyPhase('dashboard-resume-fast-executor', {
        serviceWorkerOwned: true,
        queueOnlyAuthority: true,
        requeueMissingActiveTabs: true
    }), timers)
    assert.equal(result.changed, false)
    assert.equal(result.reason, 'executor-cases-unresolved')
    assert.equal(result.primaryUnresolvedCase?.case, 'active-with-tab-and-pending-action')
    assert.equal(result.primaryUnresolvedCase?.reason, 'missing-tab')
    assert.equal(sw.state().activeQueuedTabs.includes(tab.id), true)
    assert.equal(browser.__removedTabs.includes(tab.id), false)
    assert.equal(getRecoveredCoordinatorQueue(storage)[href].status, 'active')
    assert.equal(sw.state().queuedTabMetadata.some(([id]) => id === tab.id), true)
    assert.equal(sw.state().hasCoordinatorReconcileTimeout, true)
    assert.equal(sw.state().queueWakeupCounters['reconcile.deferred.freshRuntimeStartupQueueOnly'] || 0, 0)
})

test('executor queue-only reconcile recovers exhausted stale active requeue', async () => {
    const href = 'https://www.quora.com/profile/Synthetic-Executor-Requeue-Continuation'
    const runId = 'run-executor-requeue-continuation'
    const attemptId = 'attempt-executor-requeue-continuation'
    const tabId = 706
    const {sw, storage} = loadServiceWorkerHarness({
        now: 5200,
        storage: {
            mbCoordinatorPaused: false,
            mbCoordinatorQueue: {
                [href]: {
                    ...makeActiveCoordinatorRow({
                        href,
                        runId,
                        attemptId,
                        tabId,
                        now: 5100
                    }),
                    retryAttempt: 0,
                    maxRetries: 1
                }
            },
            mbCoordinatorRuns: {
                [runId]: makeCoordinatorRun({href, runId})
            },
            mbCoordinatorEvents: [],
            [LEGACY_PROFILE_PROGRESS_KEY]: {
                [href]: {
                    profileHref: href,
                    actionKind: 'mute-block',
                    status: 'queued',
                    tabId,
                    attemptId,
                    attemptNumber: 1,
                    retryAttempt: 0,
                    maxRetries: 1,
                    updatedAt: 5100
                }
            }
        }
    })

    const result = await sw.runCoordinatorExecutorApplyPhase('synthetic-queue-only-requeue', {
        serviceWorkerOwned: true,
        queueOnlyAuthority: true,
        requeueMissingActiveTabs: true,
        forceDurableQueueReload: true
    })

    const freshActiveWait = result.unresolvedExecutorCases?.some?.(item =>
        item.case === 'active-missing-tab' &&
        item.reason === 'fresh-active-open-waiting-for-actor') === true
    if(freshActiveWait) {
        assert.equal(result.reason, 'executor-cases-unresolved')
        assert.equal(getRecoveredCoordinatorQueue(storage)[href].status, 'active')
        const residentRow = sw.coordinatorAuthority.current().queue[href] || null
        if(residentRow) assert.equal(residentRow.status, 'active')
    }
    else {
        assert.equal(result.changed, true)
        assert.equal(result.reason, 'requeued-missing-active-tabs')
        assert.equal(result.requeued, 1)
        assert.equal(result.queued, 0)
        assert.equal(result.pending, 0)
        assert.equal(getRecoveredCoordinatorQueue(storage)[href].status, 'queued')
        assert.equal(sw.coordinatorAuthority.current().queue[href].status, 'queued')
        assert.notEqual(sw.coordinatorAuthority.current().queue[href].attemptId, attemptId)
        assert.equal(sw.coordinatorAuthority.current().queue[href].tabId, null)
    }
    const finalRow = sw.coordinatorAuthority.current().queue[href] || getRecoveredCoordinatorQueue(storage)[href]
    assert.notEqual(finalRow.error, 'Queued tab failed to open after exhausting retry budget')
    assert.notEqual(finalRow.actionLeaseReleaseReason, 'executor-plan-active-transition-retry-budget-exhausted')
    if(finalRow.actionLeaseReleaseReason) {
        assert.match(finalRow.actionLeaseReleaseReason, /active-missing-tab|retry-budget-recovered/)
    }
    if(!freshActiveWait) {
        assert.equal(sw.state().activeQueuedTabs.includes(tabId), false)
    }
    assert.equal(sw.state().queuedTabActions.some(action => action.profileHref === href || action.coordinatorKey === href), false)
    assert.equal(sw.state().hasCoordinatorQueueResumeTimeout, true)
    assert.equal(sw.state().hasCoordinatorReconcileTimeout, true)
    if(!freshActiveWait) {
        assert.equal(sw.state().queueWakeupCounters['reconcile.executor.changed.requeuedMissingActiveTab'], 1)
        assert.equal(sw.state().queueWakeupCounters['reconcile.executor.changed.requeuedMissingActiveTabTerminalized'] || 0, 0)
    }
})

